//
// Ring 050: Test runner implementation per T27-MATH-PHYSICS-TEST-FRAMEWORK-SPEC.md
// Entry point for `tri test <spec.t27>` execution

module runner;

use core::{TestResult, Verdict, ToleranceTier, EngineeringStatus, GatePipeline, for_all, metamorphic, differential, TapReporter, JsonReporter};

/// Test runner configuration
struct TestRunnerConfig {
    /// Maximum number of iterations for property-based tests
    max_iterations: u32,
    /// Default tolerance for numeric comparisons
    default_tolerance: f64,
    /// Whether to generate detailed reports
    verbose: bool,
    /// Output format (tap, json, both)
    output_format: string
}

impl TestRunnerConfig {
    fn default() -> TestRunnerConfig {
        TestRunnerConfig {
            max_iterations: 10000,
            default_tolerance: 1e-12,
            verbose: false,
            output_format: "tap".to_string()
        }
    }

    fn with_iterations(self, iterations: u32) -> TestRunnerConfig {
        TestRunnerConfig { max_iterations: iterations, ..self }
    }

    fn with_tolerance(self, tolerance: f64) -> TestRunnerConfig {
        TestRunnerConfig { default_tolerance: tolerance, ..self }
    }

    fn with_verbose(self, verbose: bool) -> TestRunnerConfig {
        TestRunnerConfig { verbose, ..self }
    }

    fn with_format(self, format: string) -> TestRunnerConfig {
        TestRunnerConfig { output_format: format, ..self }
    }
}

/// Test runner state
struct TestRunner {
    config: TestRunnerConfig,
    results: Vec<TestResult>,
    start_time: f64  // Using f64 for timestamp
}

impl TestRunner {
    fn new(config: TestRunnerConfig) -> TestRunner {
        TestRunner {
            config,
            results: Vec::new(),
            start_time: current_timestamp()
        }
    }

    /// Execute a single test specification
    fn run_test_spec(&mut self, spec_path: string) -> Result<Vec<TestResult>, string> {
        // Parse the .t27 specification
        let spec_content = read_file(spec_path)?;
        let spec = parse_t27_spec(spec_content)?;

        // Execute all test blocks in the spec
        let mut test_results = Vec::new();

        for test_block in spec.test_blocks {
            let result = self.execute_test_block(test_block)?;
            test_results.push(result);
        }

        Ok(test_results)
    }

    /// Execute a single test block
    fn execute_test_block(&mut self, test_block: TestBlock) -> Result<TestResult, string> {
        match test_block.kind {
            TestKind::Unit => self.execute_unit_test(test_block),
            TestKind::Property => self.execute_property_test(test_block),
            TestKind::Invariant => self.execute_invariant_test(test_block),
            TestKind::Bench => self.execute_benchmark_test(test_block),
            TestKind::GatePipeline => self.execute_gate_pipeline_test(test_block)
        }
    }

    /// Execute unit test
    fn execute_unit_test(&mut self, test_block: TestBlock) -> Result<TestResult, string> {
        let start = current_timestamp();

        // Execute the test logic
        let result = test_block.test_fn();
        let duration = current_timestamp() - start;

        Ok(TestResult {
            name: test_block.name,
            verdict: if result { Verdict::CLEAN } else { Verdict::FAIL },
            tolerance: test_block.tolerance_tier.unwrap_or(ToleranceTier::EXACT),
            engineering: EngineeringStatus::tested,
            claim_id: test_block.claim_id,
            input: test_block.input,
            expected: test_block.expected,
            actual: result,
            delta: None,
            message: if result { None } else { Some("Unit test failed".to_string()) }
        })
    }

    /// Execute property-based test
    fn execute_property_test(&mut self, test_block: TestBlock) -> Result<TestResult, string> {
        let iterations = test_block.iterations.unwrap_or(self.config.max_iterations);
        let domain = test_block.domain_fn.unwrap_or(|| default_domain());
        let property = test_block.property_fn.unwrap_or(default_property());

        let result = for_all(domain, property, iterations);

        Ok(result)
    }

    /// Execute invariant test
    fn execute_invariant_test(&mut self, test_block: TestBlock) -> Result<TestResult, string> {
        // Invariant tests are always property tests with exact tolerance
        let mut invariant_block = test_block;
        invariant_block.tolerance_tier = Some(ToleranceTier::EXACT);
        self.execute_property_test(invariant_block)
    }

    /// Execute benchmark test
    fn execute_benchmark_test(&mut self, test_block: TestBlock) -> Result<TestResult, string> {
        let start = current_timestamp();

        // Run the benchmark operation multiple times
        let iterations = test_block.iterations.unwrap_or(1000);
        for _ in 0..iterations {
            let _ = test_block.test_fn();
        }

        let duration = current_timestamp() - start;
        let avg_time = duration / iterations as f64;

        Ok(TestResult {
            name: format!("{}_bench", test_block.name),
            verdict: Verdict::CLEAN,  // Benchmarks don't fail unless error
            tolerance: ToleranceTier::EMPIRICAL_FIT,
            engineering: EngineeringStatus::empirical,
            claim_id: test_block.claim_id,
            input: iterations,
            expected: 0.0,  // Expected execution time
            actual: avg_time,
            delta: None,
            message: Some(format!("Average execution time: {:.6}s", avg_time))
        })
    }

    /// Execute gate pipeline test
    fn execute_gate_pipeline_test(&mut self, test_block: TestBlock) -> Result<TestResult, string> {
        let pipeline = test_block.pipeline_fn.unwrap_or(default_pipeline())();
        let verdict = pipeline.verdict();

        Ok(TestResult {
            name: format!("{}_pipeline", test_block.name),
            verdict,
            tolerance: ToleranceTier::EXACT,
            engineering: EngineeringStatus::tested,
            claim_id: test_block.claim_id,
            input: test_block.input,
            expected: GatePipeline::all_true(),
            actual: pipeline,
            delta: None,
            message: if verdict == Verdict::FAIL { 
                Some("Gate pipeline failed - check which gates are false".to_string()) 
            } else { None }
        })
    }

    /// Generate test reports
    fn generate_reports(&self) -> string {
        let mut output = String::new();

        if self.config.output_format.contains("tap") || self.config.output_format.contains("both") {
            let tap_reporter = TapReporter::new(self.results.clone());
            output.push_str("=== TAP Report ===\n");
            output.push_str(&tap_reporter.generate_tap());
            output.push_str("\n");
        }

        if self.config.output_format.contains("json") || self.config.output_format.contains("both") {
            let json_reporter = JsonReporter::new(self.results.clone());
            output.push_str("=== JSON Report ===\n");
            output.push_str(&json_reporter.generate_json());
            output.push_str("\n");
        }

        output
    }

    /// Print summary statistics
    fn print_summary(&self) {
        let total = self.results.len();
        let passed = self.results.iter().filter(|r| r.verdict == Verdict::CLEAN).count();
        let failed = self.results.iter().filter(|r| r.verdict == Verdict::FAIL).count();
        let skipped = self.results.iter().filter(|r| r.verdict == Verdict::SKIP).count();
        let partial = self.results.iter().filter(|r| r.verdict == Verdict::PARTIAL).count();

        println!("=== Test Summary ===");
        println!("Total tests: {}", total);
        println!("Passed: {}", passed);
        println!("Failed: {}", failed);
        println!("Skipped: {}", skipped);
        println!("Partial: {}", partial);

        if failed > 0 {
            println!("\n=== Failed Tests ===");
            for result in &self.results {
                if result.verdict == Verdict::FAIL {
                    println!("0 {}", result.name);
                    if let Some(ref msg) = result.message {
                        println!("   {}", msg);
                    }
                }
            }
        }

        if self.config.verbose {
            println!("\n=== All Results ===");
            for result in &self.results {
                let status = match result.verdict {
                    Verdict::CLEAN => "1",
                    Verdict::FAIL => "2", 
                    Verdict::SKIP => "3",
                    Verdict::PARTIAL => "~"
                };
                println!("{} {} ({})", status, result.name, result.engineering);
            }
        }
    }

    /// Exit with appropriate code based on test results
    fn exit_with_code(&self) -> ! {
        let failed = self.results.iter().filter(|r| r.verdict == Verdict::FAIL).count();

        if failed > 0 {
            std::process::exit(1);
        } else {
            std::process::exit(0);
        }
    }
}

