}

/// Execute test specification with custom configuration
pub fn run_test_spec_file_with_config(spec_path: string, config: TestRunnerConfig) -> Result<(), string> {
    let mut runner = TestRunner::new(config);

    // Run the test specification
    let results = runner.run_test_spec(spec_path)?;
    runner.results = results;

    // Generate reports
    let reports = runner.generate_reports();
    if runner.config.verbose {
        println!("{}", reports);
    }

    // Print summary
    runner.print_summary();

    // Exit with appropriate code
    runner.exit_with_code();
}

/// Command-line interface for test runner
pub fn main(args: Vec<string>) -> Result<(), string> {
    let mut config = TestRunnerConfig::default();
    let mut spec_files = Vec::new();

    // Parse command line arguments
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--iterations" | "-i" => {
                if i + 1 < args.len() {
                    config.max_iterations = args[i + 1].parse::<u32>().map_err(|_| "Invalid iteration count".to_string())?;
                    i += 1;
                }
            }
            "--tolerance" | "-t" => {
                if i + 1 < args.len() {
                    config.default_tolerance = args[i + 1].parse::<f64>().map_err(|_| "Invalid tolerance".to_string())?;
                    i += 1;
                }
            }
            "--verbose" | "-v" => {
                config.verbose = true;
            }
            "--format" | "-f" => {
                if i + 1 < args.len() {
                    config.output_format = args[i + 1].clone();
                    i += 1;
                }
            }
            "--help" | "-h" => {
                print_help();
                return Ok(());
            }
            _ => {
                if !args[i].starts_with("-") {
                    spec_files.push(args[i].clone());
                }
            }
        }
        i += 1;
    }

    if spec_files.is_empty() {
        return Err("No test specification files provided".to_string());
    }

    // Run all specified test files
    let mut overall_success = true;
    for spec_file in spec_files {
        if let Err(err) = run_test_spec_file_with_config(spec_file, config.clone()) {
            eprintln!("Error running {}: {}", spec_file, err);
            overall_success = false;
        }
    }

    if !overall_success {
        std::process::exit(1);
    }

    Ok(())
}

