// SPDX-License-Identifier: Apache-2.0
// Module: Sequence Hyperdimensional Computing (HDC)
// phi^2 + 1/phi^2 = 3 | TRINITY

module SequenceHdc {
    // ========================================================================
    // IMPORTS - Reference existing specs, DO NOT DUPLICATE
    // ========================================================================
    use base::types;      // Trit enum
    use numeric::gf16;    // GF16 for similarity scores
    use ternary::packed_trit;  // PackedBigInt for HV storage

    // ========================================================================
    // 1. Constants
    // ========================================================================

    // N-gram order for sequence encoding
    pub const NGRAM_ORDER : u16 = 3;

    // Default dimension for hypervectors
    pub const DEFAULT_DIM : u16 = 1000;

    // Number of printable ASCII characters in alphabet
    pub const HEBDIAN_CHARS : usize = 95;

    // ASCII offset for printable characters
    pub const HEBDIAN_OFFSET : usize = 32;

    // ========================================================================
    // 2. Item Memory Type
    // ========================================================================

    // ItemMemory: Maps symbols to random hypervectors
    // Uses JIT engine for VSA operations, caches computed vectors
    // Thread-safe access via allocator-based hash map
    pub struct ItemMemory {
        allocator_id : u16,        // Allocator identifier
        dimension : usize,          // Hypervector dimension
        seed : u64,              // Seed for random generation
        cache : map<u32, PackedBigInt>, // Symbol -> HV cache
    }

    // ========================================================================
    // 3. N-gram Encoder Type
    // ========================================================================

    // NGramEncoder: Encodes sequences using n-gram permutations
    // Uses permutation + bind operations with JIT acceleration
    // Complexity: O(n) per encode where n = string length
    pub struct NGramEncoder {
        item_memory : *ItemMemory,  // Shared item memory reference
        jit_enabled : bool,             // JIT acceleration enabled flag
    }

    // ========================================================================
    // 4. Sequence Memory Type
    // ========================================================================

    // SequenceMemory: Stores encoded sequences with labels
    // Supports similarity queries and top-k retrieval
    // Thread-safe access via allocator-based hash map
    pub struct SequenceMemory {
        allocator_id : u16,        // Allocator identifier
        n : u16,                       // N-gram order for encoding
        item_memory : *ItemMemory,    // Reference to item memory
        sequences : map<u64, PackedBigInt>, // Label -> encoded sequence
        jit_enabled : bool,             // JIT acceleration enabled flag
    }

    // ========================================================================
    // 5. Sequence Types
    // ========================================================================

    // EncodedSequence: Label with encoded n-gram vector
    // Stores result of n-gram encoding
    pub struct EncodedSequence {
        label : []const u8,        // Label for the sequence
        vector : PackedBigInt,        // N-gram encoded vector
    }

    // QueryResult: Result of sequence similarity query
    // Stores matching sequence and similarity score
    pub struct QueryResult {
        label : []const u8,        // Matching sequence label
        similarity : f64,          // Cosine similarity score
    }

    // ========================================================================
    // 6. Item Memory Functions
    // ========================================================================

    // initItemMemory(allocator: std.mem.Allocator, dimension: usize, seed: u64) -> ItemMemory
    // Create new item memory with given dimension and seed
    // Initializes allocator and hash map
    // Complexity: O(1)
    pub fn initItemMemory(allocator_id: u16, dimension: usize, seed: u64) -> ItemMemory;

    // deinitItemMemory(item_memory: &ItemMemory)
    // Destroy item memory and free resources
    // Deallocates hash map and allocator
    // Complexity: O(n) where n = cached items
    pub fn deinitItemMemory(item_memory: &ItemMemory);

    // getVector(item_memory: &ItemMemory, symbol: u32) -> ?PackedBigInt
    // Get hypervector for symbol (create if not exists)
    // Returns vector pointer or null if not found
    // Complexity: O(1) for hash lookup
    pub fn getVector(item_memory: &ItemMemory, symbol: u32) -> ?PackedBigInt;

    // ========================================================================
    // 7. N-gram Encoder Functions
    // ========================================================================

    // initEncoder(item_memory: &ItemMemory, n: u16) -> NGramEncoder
    // Create n-gram encoder with configured order
    // Returns encoder ready for encoding operations
    // Complexity: O(1)
    pub fn initEncoder(item_memory: &ItemMemory, n: u16) -> NGramEncoder;

    // encodeNGram(encoder: &NGramEncoder, chars: []const u8) -> !EncodedSequence
    // Encode a character sequence as n-gram vector
    // Uses permutation + bind with JIT acceleration
    // Complexity: O(len) where len = chars.length * n
    pub fn encodeNGram(encoder: &NGramEncoder, chars: []const u8) -> !EncodedSequence;

    // ========================================================================
    // 8. Sequence Memory Functions
    // ========================================================================

    // initSequenceMemory(allocator: std.mem.Allocator, n: u16, seed: u64) -> SequenceMemory
    // Create new sequence memory with given n-gram order
    // Initializes hash map for sequence storage
    // Complexity: O(1)
    pub fn initSequenceMemory(allocator_id: u16, n: u16, seed: u64) -> SequenceMemory;

    // deinitSequenceMemory(seq_mem: &SequenceMemory)
    // Destroy sequence memory and free resources
    // Deallocates hash map and allocator
    // Complexity: O(n) where n = stored sequences
    pub fn deinitSequenceMemory(seq_mem: &SequenceMemory);

    // store(seq_mem: &SequenceMemory, label: []const u8, str: []const u8)
    // Encode and store a labeled sequence
    // Returns encoded n-gram vector for the sequence
    // Complexity: O(len) where len = str.length * n
    pub fn store(seq_mem: &SequenceMemory, label: []const u8, str: []const u8);

    // query(seq_mem: &SequenceMemory, str: []const u8, k: usize) -> ?QueryResult
    // Find top-k most similar sequences to query
    // Returns best matching sequence with similarity score
    // Complexity: O(n * m) where n = stored sequences, m = NGRAM_ORDER * len
    pub fn query(seq_mem: &SequenceMemory, str: []const u8, k: usize) -> ?QueryResult;

    // queryTopK(seq_mem: &SequenceMemory, k: usize) -> []QueryResult
    // Find top-k most similar sequences
    // Returns array of top-k results sorted by similarity
    // Complexity: O(n * m * k) for full scan
    pub fn queryTopK(seq_mem: &SequenceMemory, k: usize) -> []QueryResult;

    // ========================================================================
    // 9. Language Detection Functions
    // ========================================================================

    // initDetector(item_memory: &ItemMemory, dimension: usize) -> LanguageDetector
    // Create language detector with given dimension
    // Returns detector ready for training and detection
    // Complexity: O(1)
    pub fn initDetector(item_memory: &ItemMemory, dimension: usize) -> LanguageDetector;

    // trainDetector(detector: &LanguageDetector, language: []const u8, samples: []const u8)
    // Train detector on labeled text samples per language
    // Stores character n-grams for each language
    // Complexity: O(p * n) where p = samples.len, n = dimension
    pub fn trainDetector(detector: &LanguageDetector, language: []const u8, samples: []const u8);

    // detect(detector: &LanguageDetector, text: []const u8) -> !SequenceMemory.QueryResult
    // Detect language of input text
    // Returns best matching language with similarity score
    // Complexity: O(n * m) where n = dimension, m = languages
    pub fn detect(detector: &LanguageDetector, text: []const u8) -> !SequenceMemory.QueryResult;

    // ========================================================================
    // TDD - Tests
    // ========================================================================

    test item_memory_get_vector_creates_on_miss
        // Verify: getVector creates new vector for missing symbol
        given item = initItemMemory(0, 100, 123)
        when result = getVector(&item, 65)
        then result != null

    test item_memory_get_vector_returns_existing
        // Verify: getVector returns cached vector for existing symbol
        given item = initItemMemory(0, 100, 123)
        when vec = getVector(&item, 65)
        and stored = getVector(&item, 65)
        then vec == stored

    test ngram_encoder_creates_valid_encoding
        // Verify: encodeNGram creates valid n-gram vector
        given item = initItemMemory(0, 100, 123)
        and encoder = initEncoder(&item, 3)
        when result = encodeNGram(&encoder, "abc")
        then result.vector.trit_count() > 0

    test ngram_encoder_same_input_same_output
        // Verify: Encoding same input produces identical output
        given item = initItemMemory(0, 100, 123)
        and encoder = initEncoder(&item, 3)
        when result1 = encodeNGram(&encoder, "abc")
        and result2 = encodeNGram(&encoder, "abc")
        then compareAbs(&result1.vector, &result2.vector) == 0

    test ngram_encoder_different_input_different_output
        // Verify: Encoding different input produces different output
        given item = initItemMemory(0, 100, 123)
        and encoder = initEncoder(&item, 3)
        when result1 = encodeNGram(&encoder, "abc")
        and result2 = encodeNGram(&encoder, "xyz")
        then compareAbs(&result1.vector, &result2.vector) != 0

    test sequence_store_creates_entry
        // Verify: store adds labeled sequence to memory
        given seq = initSequenceMemory(0, 3, 123)
        when store(&seq, "hello", "hello")
        then query(&seq, "hello", 1) != null

    test sequence_query_finds_best_match
        // Verify: query returns most similar sequence
        given seq = initSequenceMemory(0, 3, 123)
        when store(&seq, "hello world", "hello world")
        and store(&seq, "hello there", "hello there")
        and result = query(&seq, "hello ther", 1)
        then result != null and result.label == "hello world"

    test detector_trains_on_samples
        // Verify: trainDetector learns from labeled samples
        given item = initItemMemory(0, 1000, 123)
        and detector = initDetector(&item, 100)
        when train(&detector, "english", "the quick brown fox")
        and train(&detector, "german", "der schnelle braune fuchs")
        and english = detect(&detector, "the quick brown fox")
        then english.label == "english"

    test detector_detects_correct_language
        // Verify: detect returns correct language for sample
        given item = initItemMemory(0, 1000, 123)
        and detector = initDetector(&item, 100)
        and _ = train(&detector, "english", "the quick brown fox")
        and result = detect(&detector, "der schnelle braune fuchs")
        then result.label == "german"

    // ========================================================================
    // TDD - Invariants
    // ========================================================================

    invariant item_memory_thread_safe
        // Verify: Item memory operations are thread-safe
        // Concurrent access must be safe via allocator locking
        assert true;

    invariant ngram_encoding_preserves_order
        // Verify: N-gram encoding preserves sequential information
        // Permutation ensures characters are processed in order
        assert true;

    invariant sequence_query_returns_subset
        // Verify: Query results reference stored sequences
        // Returned labels must be from stored sequences
        assert true;

    invariant language_detector_separates_languages
        // Verify: Detector can distinguish between trained languages
        // Languages should have distinct signatures
        assert true;

    invariant query_similarity_normalized
        // Verify: Query similarity is normalized [-1.0, 1.0]
        // Cosine similarity must be in valid range
        assert true;

    // ========================================================================
    // TDD - Benchmarks
    // ========================================================================

    bench ngram_encode_latency_10_chars
        // Measure: cycles to encode 10-character sequence
        // Target: < 50000 cycles (JIT-accelerated n-gram encoding)
        @setEvalBranchQuota(10000);
        var item = initItemMemory(0, 1000, 123);
        var encoder = initEncoder(&item, 3);
        _ = encodeNGram(&encoder, "hello world");
        _ = encoder;

    bench ngram_decode_latency_10_chars
        // Measure: cycles to decode 10-character sequence
        // Target: < 50000 cycles (VSA operations + similarity search)
        @setEvalBranchQuota(10000);
        var seq = initSequenceMemory(0, 3, 123);
        var _ = store(&seq, "test", "test");
        _ = query(&seq, "test", 1);
        _ = seq;

    bench sequence_query_latency_100_entries
        // Measure: cycles to query top-k from 100 entries
        // Target: < 200000 cycles (similarity comparisons)
        @setEvalBranchQuota(10000);
        var seq = initSequenceMemory(0, 3, 123);
        for (0..100) |_| {
            _ = store(&seq, "entry", "entry");
        }
        _ = query(&seq, "query", 10);
        _ = seq;

    bench detector_train_latency
        // Measure: cycles to train detector on 2 languages
        // Target: < 100000 cycles (n-gram encoding per sample)
        @setEvalBranchQuota(10000);
        var item = initItemMemory(0, 1000, 123);
        var detector = initDetector(&item, 1000);
        _ = train(&detector, "english", "the quick brown fox");
        _ = train(&detector, "german", "der schnelle braune fuchs");
        _ = detector;

    bench item_memory_cache_hit_latency
        // Measure: cycles for cache hit (vector already exists)
        // Target: < 200 cycles (hash map lookup)
        @setEvalBranchQuota(10000);
        var item = initItemMemory(0, 100, 123);
        var vec = getVector(&item, 65);
        _ = getVector(&item, 65);
        _ = item;

    bench item_memory_cache_miss_latency
        // Measure: cycles for cache miss (needs vector creation)
        // Target: < 1000 cycles (hash insert + vector generation)
        @setEvalBranchQuota(10000);
        var item = initItemMemory(0, 100, 123);
        _ = getVector(&item, 66);
        _ = item;
