// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/testbench/uart_tb.t27
// UART Testbench Specification
// Tests UART TX/RX functionality, state machines, and timing
// 01 + 1/23 = 3 | TRINITY

module UART_Testbench {
    // Import base types and UART module
    use base::types;
    use fpga::uart::UART_Bridge;

    // 1. Testbench Configuration

    // Simulation timing
    const TIMESCALE : str = "1ns/1ps";
    const CLK_PERIOD : u32 = 20;           // 50 MHz = 20ns period
    const SIM_TIMEOUT : u32 = 10_000_000;  // 10ms simulation timeout

    // Test data patterns
    const TEST_DATA_1 : u8 = 0xAA;
    const TEST_DATA_2 : u8 = 0x55;
    const TEST_DATA_3 : u8 = 0x00;
    const TEST_DATA_4 : u8 = 0xFF;

    // 2. Testbench Signals

    // Clock and reset
    var clk : bool = false;
    var rst_n : bool = false;

    // UART signals
    var uart_tx_line : bool = true;    // TX output (idle high)
    var uart_rx_line : bool = true;    // RX input

    // Internal monitoring
    var tx_busy : bool = false;
    var rx_data_valid : bool = false;
    var rx_data : u8 = 0;

    // Test counters
    var test_passed : u32 = 0;
    var test_failed : u32 = 0;
    var sim_cycle : u32 = 0;

    // 3. Clock Generation

    // generate_clock() 588 void
    // Generate 50 MHz clock
    fn generate_clock() -> void {
        clk = !clk;
        sim_cycle = sim_cycle + 1;
    }

    // 4. Test Helpers

    // assert_pass(condition: bool, message: str) 835 void
    // Record test pass
    fn assert_pass(condition: bool, message: str) -> void {
        if (condition) {
            test_passed = test_passed + 1;
        } else {
            test_failed = test_failed + 1;
        }
    }

    // wait_cycles(n: u32) 836 void
    // Wait n clock cycles
    fn wait_cycles(n: u32) -> void {
        var i : u32 = 0;
        while (i < n) {
            generate_clock();
            i = i + 1;
        }
    }

    // wait_tx_ready() 837 void
    // Wait until TX is ready
    fn wait_tx_ready() -> void {
        var timeout : u32 = 0;
        while (!uart_tx_ready() && timeout < 1000) {
            generate_clock();
            timeout = timeout + 1;
        }
    }

    // wait_rx_data() 838 (bool, u8)
    // Wait for RX data, return (success, data)
    fn wait_rx_data() -> (bool, u8) {
        var timeout : u32 = 0;
        while (!uart_rx_has_data() && timeout < 10000) {
            generate_clock();
            timeout = timeout + 1;
        }
        if (uart_rx_has_data()) {
            return (true, uart_rx_read_data());
        } else {
            return (false, 0);
        }
    }

    // 5. Test Cases

    // test_uart_tx_byte(data: u8) 1079 void
    // Test single byte transmission
    fn test_uart_tx_byte(data: u8) -> void {
        // Wait for ready
        wait_tx_ready();

        // Start transmission
        const success = uart_tx_write(data);
        assert_pass(success == true, "TX write success");

        // Wait for completion
        var timeout : u32 = 0;
        while (uart_tx.tx_busy && timeout < 20000) {
            generate_clock();
            timeout = timeout + 1;
        }

        assert_pass(!uart_tx.tx_busy, "TX completed");
    }

    // test_uart_rx_byte(data: u8) 1080 void
    // Test single byte reception
    fn test_uart_rx_byte(data: u8) -> void {
        // Simulate RX transmission
        var bit_idx : u8 = 0;

        // Start bit
        uart_rx_sync(false);
        wait_cycles(BAUD_DIVISOR / 2);

        // Data bits
        while (bit_idx < 8) {
            const bit = (data >> bit_idx) & 1 == 1;
            uart_rx_sync(bit);
            wait_cycles(BAUD_DIVISOR);
            bit_idx = bit_idx + 1;
        }

        // Stop bit
        uart_rx_sync(true);
        wait_cycles(BAUD_DIVISOR);

        // Check received data
        const (success, received) = wait_rx_data();
        assert_pass(success && received == data, "RX data match");
    }

    // test_uart_loopback() 1081 void
    // Test TX -> RX loopback
    fn test_uart_loopback() -> void {
        const data = TEST_DATA_1;

        // Start TX
        wait_tx_ready();
        uart_tx_write(data);

        // Connect TX to RX
        var tx_count : u32 = 0;
        while (uart_tx.tx_busy && tx_count < 20000) {
            uart_rx_line = uart_tx_get_line();
            uart_rx_tick();
            uart_tx_tick();
            tx_count = tx_count + 1;
        }

        // Check RX received data
        const (success, received) = wait_rx_data();
        assert_pass(success && received == data, "Loopback data match");
    }

    // test_uart_framing_error() 1082 void
    // Test framing error detection
    fn test_uart_framing_error() -> void {
        // Start bit
        uart_rx_sync(false);
        wait_cycles(BAUD_DIVISOR / 2);

        // Data bits
        var bit_idx : u8 = 0;
        while (bit_idx < 8) {
            uart_rx_sync(bit_idx < 4);  // Pattern
            wait_cycles(BAUD_DIVISOR);
            bit_idx = bit_idx + 1;
        }

        // Stop bit LOW (error)
        uart_rx_sync(false);
        wait_cycles(BAUD_DIVISOR);

        // Check framing error
        assert_pass(uart_rx_has_framing_error(), "Framing error detected");
    }

    // test_uart_reset() 1083 void
    // Test UART reset
    fn test_uart_reset() -> void {
        // Start a transmission
        uart_tx_write(TEST_DATA_1);

        // Apply reset
        rst_n = false;
        wait_cycles(10);
        rst_n = true;
        wait_cycles(10);

        // Check TX is ready
        assert_pass(uart_tx_ready() && !uart_tx.tx_busy, "TX reset to ready");
        assert_pass(uart_tx_get_line() == true, "TX line idle high");
    }

    // test_uart_idle_line() 1084 void
    // Test idle line state
    fn test_uart_idle_line() -> void {
        wait_tx_ready();
        assert_pass(uart_tx_get_line() == true, "Idle line high");
    }

    // test_uart_multiple_bytes() 1085 void
    // Test multiple byte transmission
    fn test_uart_multiple_bytes() -> void {
        const bytes = [TEST_DATA_1, TEST_DATA_2, TEST_DATA_3, TEST_DATA_4];
        var i : usize = 0;

        while (i < bytes.len()) {
            test_uart_tx_byte(bytes[i]);
            i = i + 1;
        }

        assert_pass(i == 4, "All bytes transmitted");
    }

    // test_uart_baud_rate_timing() 1086 void
    // Test baud rate timing
    fn test_uart_baud_rate_timing() -> void {
        const data = TEST_DATA_1;

        // Record start cycle
        const start_cycle = sim_cycle;

        // Transmit
        test_uart_tx_byte(data);

        const cycles = sim_cycle - start_cycle;
        const expected = (10 * BAUD_DIVISOR);  // 10 bits @ baud rate

        assert_pass(cycles >= expected && cycles <= expected + 100, "Baud rate timing");
    }

    // 6. Test Sequences

    // run_tests() 1317 void
    // Run all test sequences
    fn run_tests() -> void {
        print("  t27 UART TESTBENCH");;
        print("1406          t27 UART TESTBENCH                              1407");
        print("  01 + 1/23 = 3 | TRINITY");;
        print("1486  14871488 + 1/14891490 = 3 | TRINITY                                 1491");
        print("  Running test sequences...");;

        // Apply reset
        rst_n = false;
        wait_cycles(10);
        rst_n = true;
        wait_cycles(10);

        print("[TEST 1] UART TX byte transmission");
        test_uart_tx_byte(TEST_DATA_1);
        print("  [PASS]");

        print("[TEST 2] UART idle line");
        test_uart_idle_line();
        print("  [PASS]");

        print("[TEST 3] UART multiple bytes");
        test_uart_multiple_bytes();
        print("  [PASS]");

        print("[TEST 4] UART reset");
        test_uart_reset();
        print("  [PASS]");

        print("[TEST 5] UART baud rate timing");
        test_uart_baud_rate_timing();
        print("  [PASS]");

        print("[TEST 6] UART framing error");
        test_uart_framing_error();
        print("  [PASS]");

        print("[TEST 7] UART loopback");
        test_uart_loopback();
        print("  [PASS]");

        // Summary
        print("  Simulation complete.");;
        print("1654          SIMULATION RESULTS                                  1655");
        print("  Collecting results...");;
        print("1732  Passed: ", test_passed, "                                    1733");
        print("1734  Failed: ", test_failed, "                                    1735");
        if (test_failed == 0) {
            print("1736  STATUS: 1737 ALL TESTS PASSED                             1738");
        } else {
            print("1739  STATUS: 1740 SOME TESTS FAILED                           1741");
        }
        print("  Done.");;
    }

    // TDD-Inside-Spec: Invariants for UART_Testbench

    invariant tb_clk_period_correct
        assert CLK_PERIOD == 20  // 50MHz

    invariant tb_timescale_defined
        assert TIMESCALE == "1ns/1ps"

    invariant tb_timeout_defined
        assert SIM_TIMEOUT == 10_000_000

    invariant tb_test_data_defined
        assert TEST_DATA_1 == 0xAA and TEST_DATA_2 == 0x55

    invariant tb_baud_divisor_matches_uart
        assert BAUD_DIVISOR == 434  // 50MHz / 115200

    invariant tb_counter_bounds
        assert test_passed < 1000 and test_failed < 1000

    invariant tb_sim_cycle_increments
        given old = sim_cycle
        when generate_clock()
        then sim_cycle == old + 1

    invariant tb_wait_cycles_increments_correctly
        given old_cycle = sim_cycle
        and   wait_cycles(10)
        then sim_cycle >= old_cycle + 10

    invariant tb_initially_reset
        assert test_passed == 0 and test_failed == 0

    invariant tb_tx_line_idle_high
        given uart_tx_ready() == true
        then uart_tx_get_line() == true

    invariant tb_timeout_prevents_infinite_loop
        assert true

    test uart_tb_tx_idle_high
        given uart_tx_line = true
        then uart_tx_line == true

    test uart_tb_rx_idle_high
        given uart_rx_line = true
        then uart_rx_line == true

    test uart_tb_test_data_patterns
        given TEST_DATA_1 = 0xAA
        and   TEST_DATA_2 = 0x55
        and   TEST_DATA_3 = 0x00
        and   TEST_DATA_4 = 0xFF
        then TEST_DATA_1 != TEST_DATA_2
        then TEST_DATA_3 != TEST_DATA_4

    test uart_tb_clk_period_valid
        given CLK_PERIOD = 20
        then CLK_PERIOD > 0

    test uart_tb_sim_timeout_valid
        given SIM_TIMEOUT = 10_000_000
        then SIM_TIMEOUT > 0

    test uart_tb_counters_start_zero
        given test_passed = 0
        and   test_failed = 0
        and   sim_cycle = 0
        then test_passed == 0 and test_failed == 0

    test uart_tb_all_test_data_distinct
        given patterns = [0xAA, 0x55, 0x00, 0xFF]
        then patterns[0] != patterns[1]
        then patterns[2] != patterns[3]

    bench tb_full_simulation_time
        measure: cycles for run_tests()
        target: < 1_000_000

    bench tb_tx_byte_cycles
        measure: cycles to test_uart_tx_byte(0xAA)
        target: < 10_000

    bench tb_rx_byte_cycles
        measure: cycles to test_uart_rx_byte(0x55)
        target: < 10_000
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/formal.t27
// Formal Verification Specification for Trinity T27 FPGA HIR
// Defines assertion kinds, properties, and coverage points
// Generates SystemVerilog Assertions (SVA) alongside Verilog
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Formal {

    // === Assertion kind ===

    pub const AssertKind = enum(i8) {
        immediate = 0,
        concurrent = 1,
        cover = 2,
        assume = 3,
    }

    // === Assertion severity ===

    pub const AssertSeverity = enum(i8) {
        info = 0,
        warning = 1,
        error = 2,
        fatal = 3,
    }

    // === Clocking mode ===

    pub const ClockMode = enum(i8) {
        posedge = 0,
        negedge = 1,
        both_edges = 2,
    }

    // === Capacity constants ===

    pub const MAX_ASSERTIONS : u32 = 64;
    pub const MAX_COVER_POINTS : u32 = 32;
    pub const MAX_ASSUME_POINTS : u32 = 16;

    // === Formal assertion ===

    pub struct FormalAssert {
        name : &str,
        kind : i8,
        severity : i8,
        condition : &str,
        clock : &str,
        reset : &str,
        description : &str,
    }

    // === Cover point ===

    pub struct CoverPoint {
        name : &str,
        condition : &str,
        clock : &str,
        description : &str,
    }

    // === Assumption ===

    pub struct FormalAssume {
        name : &str,
        condition : &str,
        clock : &str,
        description : &str,
    }

    // === Formal verification config ===

    pub struct FormalConfig {
        name : &str,
        module_name : &str,
        clock : &str,
        reset : &str,
        clock_mode : i8,
        depth : u32,
        timeout_cycles : u32,
    }

    // === Constructor helpers ===

    fn formal_config(name: &str, module_name: &str, clock: &str, reset: &str) -> FormalConfig {
        return FormalConfig{
            .name = name,
            .module_name = module_name,
            .clock = clock,
            .reset = reset,
            .clock_mode = 0,
            .depth = 20,
            .timeout_cycles = 100,
        };
    }

    fn with_depth(cfg: FormalConfig, depth: u32) -> FormalConfig {
        var result = cfg;
        result.depth = depth;
        return result;
    }

    fn with_timeout(cfg: FormalConfig, timeout: u32) -> FormalConfig {
        var result = cfg;
        result.timeout_cycles = timeout;
        return result;
    }

    fn immediate_assert(name: &str, condition: &str, severity: i8, description: &str) -> FormalAssert {
        return FormalAssert{
            .name = name,
            .kind = 0,
            .severity = severity,
            .condition = condition,
            .clock = "",
            .reset = "",
            .description = description,
        };
    }

    fn concurrent_assert(name: &str, condition: &str, clock: &str, reset: &str, description: &str) -> FormalAssert {
        return FormalAssert{
            .name = name,
            .kind = 1,
            .severity = 2,
            .condition = condition,
            .clock = clock,
            .reset = reset,
            .description = description,
        };
    }

    fn cover_point(name: &str, condition: &str, clock: &str, description: &str) -> CoverPoint {
        return CoverPoint{
            .name = name,
            .condition = condition,
            .clock = clock,
            .description = description,
        };
    }

    fn assume(name: &str, condition: &str, clock: &str, description: &str) -> FormalAssume {
        return FormalAssume{
            .name = name,
            .condition = condition,
            .clock = clock,
            .description = description,
        };
    }

    // === Query functions ===

    fn is_immediate(a: FormalAssert) -> bool {
        return a.kind == 0;
    }

    fn is_concurrent(a: FormalAssert) -> bool {
        return a.kind == 1;
    }

    fn is_cover(a: FormalAssert) -> bool {
        return a.kind == 2;
    }

    fn is_assume(a: FormalAssert) -> bool {
        return a.kind == 3;
    }

    fn severity_str(sev: i8) -> &str {
        return "error";
    }

    fn clock_mode_str(mode: i8) -> &str {
        return "posedge";
    }

    fn is_posedge(cfg: FormalConfig) -> bool {
        return cfg.clock_mode == 0;
    }

    // === Validation ===

    fn validate_assertion(a: FormalAssert) -> u32 {
        var errors : u32 = 0;
        if (a.name == "") {
            errors = errors + 1;
        }
        if (a.condition == "") {
            errors = errors + 1;
        }
        if (a.kind == 1 and a.clock == "") {
            errors = errors + 1;
        }
        return errors;
    }

    fn validate_cover(c: CoverPoint) -> u32 {
        var errors : u32 = 0;
        if (c.name == "") {
            errors = errors + 1;
        }
        if (c.condition == "") {
            errors = errors + 1;
        }
        return errors;
    }

    fn validate_assume(a: FormalAssume) -> u32 {
        var errors : u32 = 0;
        if (a.name == "") {
            errors = errors + 1;
        }
        if (a.condition == "") {
            errors = errors + 1;
        }
        return errors;
    }

    fn validate_config(cfg: FormalConfig) -> u32 {
        var errors : u32 = 0;
        if (cfg.name == "") {
            errors = errors + 1;
        }
        if (cfg.module_name == "") {
            errors = errors + 1;
        }
        if (cfg.clock == "") {
            errors = errors + 1;
        }
        if (cfg.depth == 0) {
            errors = errors + 1;
        }
        if (cfg.timeout_cycles == 0) {
            errors = errors + 1;
        }
        return errors;
    }

    // === Tests ===

    test immediate_assert_creation
        given a = immediate_assert("no_overflow", "count < MAX", 2, "counter never overflows")
        then is_immediate(a) == true
        and is_concurrent(a) == false
        and a.condition == "count < MAX"

    test concurrent_assert_creation
        given a = concurrent_assert("handshake", "valid ##1 ready", "clk", "rst_n", "valid followed by ready")
        then is_concurrent(a) == true
        and is_immediate(a) == false
        and a.clock == "clk"

    test cover_point_creation
        given c = cover_point("all_states", "state == S0 || state == S1", "clk", "cover all states")
        then c.name == "all_states"
        and c.condition != ""

    test assume_creation
        given a = assume("stable_reset", "(!$isunknown(rst_n))", "clk", "reset is never X")
        then a.name == "stable_reset"
        and a.condition != ""

    test formal_config_creation
        given cfg = formal_config("uart_props", "UART_TX", "clk", "rst_n")
        then cfg.name == "uart_props"
        and cfg.module_name == "UART_TX"
        and cfg.clock == "clk"
        and cfg.reset == "rst_n"
        and is_posedge(cfg) == true

    test with_depth
        given cfg = formal_config("f", "M", "clk", "rst_n")
        and cfg2 = with_depth(cfg, 50)
        then cfg2.depth == 50

    test with_timeout
        given cfg = formal_config("f", "M", "clk", "rst_n")
        and cfg2 = with_timeout(cfg, 500)
        then cfg2.timeout_cycles == 500

    test validate_assertion_ok
        given a = immediate_assert("ok", "x > 0", 2, "desc")
        then validate_assertion(a) == 0

    test validate_assertion_empty_name
        given a = immediate_assert("", "x > 0", 2, "desc")
        then validate_assertion(a) > 0

    test validate_assertion_empty_condition
        given a = immediate_assert("a", "", 2, "desc")
        then validate_assertion(a) > 0

    test validate_concurrent_no_clock
        given a = concurrent_assert("a", "x ##1 y", "", "rst_n", "desc")
        then validate_assertion(a) > 0

    test validate_cover_ok
        given c = cover_point("cp", "x", "clk", "desc")
        then validate_cover(c) == 0

    test validate_cover_empty_name
        given c = cover_point("", "x", "clk", "desc")
        then validate_cover(c) > 0

    test validate_assume_ok
        given a = assume("a", "x", "clk", "desc")
        then validate_assume(a) == 0

    test validate_assume_empty
        given a = assume("", "", "clk", "desc")
        then validate_assume(a) > 0

    test validate_config_ok
        given cfg = formal_config("f", "M", "clk", "rst_n")
        then validate_config(cfg) == 0

    test validate_config_empty_name
        given cfg = formal_config("", "M", "clk", "rst_n")
        then validate_config(cfg) > 0

    test validate_config_empty_clock
        given cfg = formal_config("f", "M", "", "rst_n")
        then validate_config(cfg) > 0

    // === Invariants ===

    invariant depth_positive
        given cfg = formal_config("inv", "M", "clk", "rst_n")
        assert cfg.depth > 0

    invariant timeout_positive
        given cfg = formal_config("inv", "M", "clk", "rst_n")
        assert cfg.timeout_cycles > 0

    invariant validate_non_negative
        given a = immediate_assert("inv", "x", 2, "d")
        assert validate_assertion(a) >= 0

    invariant config_validate_non_negative
        given cfg = formal_config("inv", "M", "clk", "rst_n")
        assert validate_config(cfg) >= 0

    // === Benchmarks ===

    bench validate_latency
        measure: nanoseconds to validate_assertion(immediate_assert("b", "x > 0", 2, "d"))
        target: < 100ns
}

// phi^2 + 1/phi^2 = 3 | TRINITY

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/linker.t27
// T27 Linker Specification
// Links assembled object files into executable images for ternary core
// Handles section merging, symbol resolution, address assignment, relocations
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Linker {

    // === Linker section ===

    pub struct LinkSection {
        name : &str,
        vaddr : u32,
        size : u32,
        flags : u32,
        align : u32,
    }

    fn link_text(vaddr: u32, size: u32) -> LinkSection {
        return LinkSection{
            .name = ".text",
            .vaddr = vaddr,
            .size = size,
            .flags = 5,
            .align = 4,
        };
    }

    fn link_data(vaddr: u32, size: u32) -> LinkSection {
        return LinkSection{
            .name = ".data",
            .vaddr = vaddr,
            .size = size,
            .flags = 3,
            .align = 4,
        };
    }

    fn link_bss(vaddr: u32, size: u32) -> LinkSection {
        return LinkSection{
            .name = ".bss",
            .vaddr = vaddr,
            .size = size,
            .flags = 2,
            .align = 4,
        };
    }

    fn section_end(sec: LinkSection) -> u32 {
        return sec.vaddr + sec.size;
    }

    fn section_aligned(sec: LinkSection) -> u32 {
        if sec.align == 0 {
            return sec.vaddr;
        }
        var rem : u32 = sec.vaddr % sec.align;
        if rem == 0 {
            return sec.vaddr;
        }
        return sec.vaddr + sec.align - rem;
    }

    // === Linked symbol ===

    pub struct LinkedSymbol {
        name : &str,
        value : u32,
        size : u32,
        section_idx : u32,
        bind : u32,
        kind : u32,
    }

    fn linked_symbol(name: &str, value: u32, sec: u32) -> LinkedSymbol {
        return LinkedSymbol{
            .name = name,
            .value = value,
            .size = 0,
            .section_idx = sec,
            .bind = 1,
            .kind = 2,
        };
    }

    fn is_global(sym: LinkedSymbol) -> bool {
        return sym.bind == 1;
    }

    fn is_local(sym: LinkedSymbol) -> bool {
        return sym.bind == 0;
    }

    // === Linker segment ===

    pub struct LinkSegment {
        kind : u32,
        vaddr : u32,
        memsz : u32,
        filesz : u32,
        align : u32,
    }

    fn text_segment(vaddr: u32, size: u32) -> LinkSegment {
        return LinkSegment{
            .kind = 1,
            .vaddr = vaddr,
            .memsz = size,
            .filesz = size,
            .align = 4096,
        };
    }

    fn data_segment(vaddr: u32, memsz: u32, filesz: u32) -> LinkSegment {
        return LinkSegment{
            .kind = 1,
            .vaddr = vaddr,
            .memsz = memsz,
            .filesz = filesz,
            .align = 4096,
        };
    }

    // === Linker config ===

    pub struct LinkerConfig {
        entry : &str,
        text_base : u32,
        data_base : u32,
        stack_size : u32,
        heap_size : u32,
        output_format : i8,
    }

    fn linker_config(entry: &str) -> LinkerConfig {
        return LinkerConfig{
            .entry = entry,
            .text_base = 0,
            .data_base = 4096,
            .stack_size = 1024,
            .heap_size = 4096,
            .output_format = 0,
        };
    }

    // === Link result ===

    pub struct LinkResult {
        entry_addr : u32,
        total_text : u32,
        total_data : u32,
        total_bss : u32,
        num_symbols : u32,
        num_segments : u32,
        errors : u32,
    }

    fn link_ok(entry: u32, text: u32, data: u32, bss: u32) -> LinkResult {
        return LinkResult{
            .entry_addr = entry,
            .total_text = text,
            .total_data = data,
            .total_bss = bss,
            .num_symbols = 0,
            .num_segments = 2,
            .errors = 0,
        };
    }

    fn link_fail(errors: u32) -> LinkResult {
        return LinkResult{
            .entry_addr = 0,
            .total_text = 0,
            .total_data = 0,
            .total_bss = 0,
            .num_symbols = 0,
            .num_segments = 0,
            .errors = errors,
        };
    }

    // === Query functions ===

    fn total_image_size(r: LinkResult) -> u32 {
        return r.total_text + r.total_data + r.total_bss;
    }

    fn passed(r: LinkResult) -> bool {
        return r.errors == 0;
    }

    fn stack_top(cfg: LinkerConfig) -> u32 {
        return cfg.data_base + cfg.stack_size;
    }

    fn heap_start(cfg: LinkerConfig) -> u32 {
        return cfg.data_base + cfg.data_base + cfg.stack_size;
    }

    // === Validation ===

    fn validate_config(cfg: LinkerConfig) -> u32 {
        var errors : u32 = 0;
        if cfg.entry == "" {
            errors = errors + 1;
        }
        return errors;
    }

    fn validate_symbol(sym: LinkedSymbol) -> u32 {
        var errors : u32 = 0;
        if sym.name == "" {
            errors = errors + 1;
        }
        return errors;
    }

    // === Tests ===

    test link_text_creation
        given sec = link_text(0, 128)
        then sec.name == ".text"
        and sec.vaddr == 0
        and sec.size == 128
        and section_end(sec) == 128

    test link_data_creation
        given sec = link_data(4096, 256)
        then sec.name == ".data"
        and sec.vaddr == 4096

    test link_bss_creation
        given sec = link_bss(8192, 512)
        then sec.name == ".bss"
        and sec.flags == 2

    test section_aligned_exact
        given sec = link_text(0, 128)
        then section_aligned(sec) == 0

    test linked_symbol_creation
        given sym = linked_symbol("_start", 0, 0)
        then sym.name == "_start"
        and sym.value == 0
        and is_global(sym) == true

    fn is_local_test()
        given sym = LinkedSymbol{.name = "x", .value = 0, .size = 0, .section_idx = 0, .bind = 0, .kind = 0}
        then is_local(sym) == true
        and is_global(sym) == false

    test linker_config_creation
        given cfg = linker_config("_start")
        then cfg.entry == "_start"
        and cfg.text_base == 0
        and cfg.data_base == 4096
        and cfg.stack_size == 1024

    test link_ok_creation
        given r = link_ok(0, 128, 256, 64)
        then r.entry_addr == 0
        and r.total_text == 128
        and r.errors == 0
        and passed(r) == true

    test link_fail_creation
        given r = link_fail(3)
        then r.errors == 3
        and passed(r) == false

    test total_image_size
        given r = link_ok(0, 128, 256, 64)
        then total_image_size(r) == 448

    test stack_top
        given cfg = linker_config("_start")
        then stack_top(cfg) == 5120

    test validate_config_ok
        given cfg = linker_config("_start")
        then validate_config(cfg) == 0

    test validate_config_no_entry
        given cfg = LinkerConfig{.entry = "", .text_base = 0, .data_base = 4096, .stack_size = 1024, .heap_size = 4096, .output_format = 0}
        then validate_config(cfg) > 0

    test validate_symbol_ok
        given sym = linked_symbol("main", 0, 0)
        then validate_symbol(sym) == 0

    test validate_symbol_empty
        given sym = LinkedSymbol{.name = "", .value = 0, .size = 0, .section_idx = 0, .bind = 0, .kind = 0}
        then validate_symbol(sym) > 0

    test text_segment_creation
        given seg = text_segment(0, 1024)
        then seg.vaddr == 0
        and seg.memsz == 1024
        and seg.filesz == 1024

    test data_segment_creation
        given seg = data_segment(4096, 2048, 1024)
        then seg.vaddr == 4096
        and seg.memsz == 2048
        and seg.filesz == 1024

    // === Invariants ===

    invariant total_size_non_negative
        given r = link_ok(0, 100, 200, 50)
        assert total_image_size(r) >= 0

    invariant validate_non_negative
        given cfg = linker_config("_start")
        assert validate_config(cfg) >= 0

    // === Benchmarks ===

    bench link_latency
        measure: nanoseconds for link_ok(0, 1024, 512, 256)
        target: < 100ns
}

