// specs/git/schema.t27
// Git Types Specification
// phi^2 + 1/phi^2 = 3 | TRINITY

module Git {
    use base::types;

    // ====================================================================
    // Git File Status Types
    // ====================================================================

    // Kind represents the type of change to a file
    enum Kind {
        Added = 0,
        Deleted = 1,
        Modified = 2,
    }

    // ====================================================================
    // Git Reference Types
    // ====================================================================

    // Base represents a git branch or reference
    struct Base {
        name: str,
        ref: str,
    }

    // ====================================================================
    // Git File Item Types
    // ====================================================================

    // Item represents a changed file with its status
    struct Item {
        file: str,
        code: str,
        status: Kind,
    }

    // Stat represents file change statistics
    struct Stat {
        file: str,
        additions: u32,
        deletions: u32,
    }

    // ====================================================================
    // Git Execution Types
    // ====================================================================

    // Options for git command execution
    struct Options {
        cwd: str,
        env: [str: str],
    }

    // Result represents the output of a git command
    struct Result {
        exit_code: u32,
        text: str,
        stdout: [u8],
        stderr: [u8],
    }

    // ====================================================================
    // Git Error Types
    // ====================================================================

    // GitError represents a git operation error
    struct GitError {
        message: str,
        exit_code: u32,
        command: [str],
    }

    // NotARepositoryError is raised when cwd is not a git repository
    struct NotARepositoryError {
        path: str,
    }

    // ====================================================================
    // Constants
    // ====================================================================

    const DEFAULT_BRANCH_MAIN: str = "main";
    const DEFAULT_BRANCH_MASTER: str = "master";
    const GIT_CONFIG_DEFAULT_BRANCH: str = "init.defaultBranch";

    // Git configuration flags
    const GIT_FLAGS: [str] = [
        "--no-optional-locks",
        "-c", "core.autocrlf=false",
        "-c", "core.fsmonitor=false",
        "-c", "core.longpaths=true",
        "-c", "core.symlinks=true",
        "-c", "core.quotepath=false",
    ];

    // ====================================================================
    // Helper Functions
    // ====================================================================

    // parse_kind parses a git status code into a Kind
    fn parse_kind(code: str) -> Kind {
        if (code == "??") {
            return Kind::Added;
        }
        if (code.contains("U")) {
            return Kind::Modified;
        }
        if (code.contains("A") && !code.contains("D")) {
            return Kind::Added;
        }
        if (code.contains("D") && !code.contains("A")) {
            return Kind::Deleted;
        }
        return Kind::Modified;
    }

    // is_success checks if a git command result indicates success
    fn is_success(result: Result) -> bool {
        return result.exit_code == 0;
    }

    // is_failure checks if a git command result indicates failure
    fn is_failure(result: Result) -> bool {
        return result.exit_code != 0;
    }

    // ====================================================================
    // Tests
    // ====================================================================

    test "kind_values" {
        var added = Kind::Added;
        var deleted = Kind::Deleted;
        var modified = Kind::Modified;
        assert(added as u32 == 0);
        assert(deleted as u32 == 1);
        assert(modified as u32 == 2);
    }

    test "base_creation" {
        var base = Base {
            name = "main",
            ref = "refs/heads/main",
        };
        assert(base.name == "main");
        assert(base.ref == "refs/heads/main");
    }

    test "item_creation" {
        var item = Item {
            file = "src/main.t27",
            code = "M",
            status = Kind::Modified,
        };
        assert(item.file == "src/main.t27");
        assert(item.status == Kind::Modified);
    }

    test "stat_creation" {
        var stat = Stat {
            file = "src/main.t27",
            additions = 10,
            deletions = 5,
        };
        assert(stat.additions == 10);
        assert(stat.deletions == 5);
    }

    test "parse_kind_untracked" {
        var kind = parse_kind("??");
        assert(kind == Kind::Added);
    }

    test "parse_kind_added" {
        var kind = parse_kind("A ");
        assert(kind == Kind::Added);
    }

    test "parse_kind_deleted" {
        var kind = parse_kind("D ");
        assert(kind == Kind::Deleted);
    }

    test "parse_kind_modified" {
        var kind = parse_kind("M ");
        assert(kind == Kind::Modified);
    }

    test "parse_kind_unmerged" {
        var kind = parse_kind("UU");
        assert(kind == Kind::Modified);
    }

    test "is_success_checks_exit_code" {
        var result = Result {
            exit_code = 0,
            text = "success",
            stdout = [],
            stderr = [],
        };
        assert(is_success(result));
        assert(!is_failure(result));
    }

    test "is_failure_checks_exit_code" {
        var result = Result {
            exit_code = 1,
            text = "error",
            stdout = [],
            stderr = [],
        };
        assert(!is_success(result));
        assert(is_failure(result));
    }

    test "git_flags_length" {
        assert(GIT_FLAGS.len == 10);
    }

    test "constants_values" {
        assert(DEFAULT_BRANCH_MAIN == "main");
        assert(DEFAULT_BRANCH_MASTER == "master");
        assert(GIT_CONFIG_DEFAULT_BRANCH == "init.defaultBranch");
    }
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/pipeline/e2e_test.t27
// Pipeline E2E Test Specification
// Ring 028 — tri pipeline end-to-end testing
// 01 + 1/23 = 3 | TRINITY

module PipelineE2E {
    use base::types;

    const MAX_PIPELINE_STAGES : usize = 10;
    const STAGE_INIT : u8 = 0;
    const STAGE_PARSE : u8 = 1;
    const STAGE_SEAL : u8 = 2;
    const STAGE_GEN : u8 = 3;
    const STAGE_TEST : u8 = 4;
    const STAGE_VERDICT : u8 = 5;
    const STAGE_SAVE : u8 = 6;
    const STAGE_COMMIT : u8 = 7;
    const STAGE_DONE : u8 = 8;
    const STAGE_FAIL : u8 = 255;

    // pipeline_run: Execute all stages sequentially, return final stage
    fn pipeline_run(stages: []u8, results: []bool, count: *usize) u8 {
        var current : u8 = STAGE_INIT;
        var i : usize = 0;
        while (i < MAX_PIPELINE_STAGES and current != STAGE_DONE and current != STAGE_FAIL) {
            stages[i] = current;
            results[i] = true;
            count.* = i + 1;

            if (current == STAGE_INIT) { current = STAGE_PARSE; }
            else if (current == STAGE_PARSE) { current = STAGE_SEAL; }
            else if (current == STAGE_SEAL) { current = STAGE_GEN; }
            else if (current == STAGE_GEN) { current = STAGE_TEST; }
            else if (current == STAGE_TEST) { current = STAGE_VERDICT; }
            else if (current == STAGE_VERDICT) { current = STAGE_SAVE; }
            else if (current == STAGE_SAVE) { current = STAGE_COMMIT; }
            else if (current == STAGE_COMMIT) { current = STAGE_DONE; }
            i = i + 1;
        }
        return current;
    }

    // pipeline_inject_failure: Simulate failure at given stage
    fn pipeline_inject_failure(fail_at: u8, stages: []u8, results: []bool, count: *usize) u8 {
        var current : u8 = STAGE_INIT;
        var i : usize = 0;
        while (i < MAX_PIPELINE_STAGES and current != STAGE_DONE and current != STAGE_FAIL) {
            stages[i] = current;
            if (current == fail_at) {
                results[i] = false;
                count.* = i + 1;
                return STAGE_FAIL;
            }
            results[i] = true;
            count.* = i + 1;

            if (current == STAGE_INIT) { current = STAGE_PARSE; }
            else if (current == STAGE_PARSE) { current = STAGE_SEAL; }
            else if (current == STAGE_SEAL) { current = STAGE_GEN; }
            else if (current == STAGE_GEN) { current = STAGE_TEST; }
            else if (current == STAGE_TEST) { current = STAGE_VERDICT; }
            else if (current == STAGE_VERDICT) { current = STAGE_SAVE; }
            else if (current == STAGE_SAVE) { current = STAGE_COMMIT; }
            else if (current == STAGE_COMMIT) { current = STAGE_DONE; }
            i = i + 1;
        }
        return current;
    }

    // stage_name: Return human-readable stage name
    fn stage_name(stage: u8) i32 {
        return stage as i32;
    }

    // pipeline_progress: Calculate completion percentage
    fn pipeline_progress(completed: usize, total: usize) f64 {
        if (total == 0) { return 0.0; }
        return (completed as f64) / (total as f64) * 100.0;
    }

    // test: full pipeline passes all stages
    test full_pipeline_pass {
        var stages : [10]u8;
        var results : [10]bool;
        var count : usize = 0;
        var final_stage = pipeline_run(stages[0..], results[0..], &count);
        try eq(final_stage, STAGE_DONE);
        try eq(count, 9);
    }

    // test: pipeline failure at gen stage
    test pipeline_fail_at_gen {
        var stages : [10]u8;
        var results : [10]bool;
        var count : usize = 0;
        var final_stage = pipeline_inject_failure(STAGE_GEN, stages[0..], results[0..], &count);
        try eq(final_stage, STAGE_FAIL);
        try eq(count, 4);
        try not(results[3]);
    }

    // test: pipeline failure at test stage
    test pipeline_fail_at_test {
        var stages : [10]u8;
        var results : [10]bool;
        var count : usize = 0;
        var final_stage = pipeline_inject_failure(STAGE_TEST, stages[0..], results[0..], &count);
        try eq(final_stage, STAGE_FAIL);
        try eq(count, 5);
    }

    // test: progress calculation
    test progress_calc {
        var pct = pipeline_progress(5, 9);
        try pct > 55.0;
        try pct < 56.0;
    }

    // invariant: pipeline stages are ordered
    invariant stage_ordering {
        STAGE_INIT < STAGE_PARSE and
        STAGE_PARSE < STAGE_SEAL and
        STAGE_SEAL < STAGE_GEN and
        STAGE_GEN < STAGE_TEST and
        STAGE_TEST < STAGE_VERDICT and
        STAGE_VERDICT < STAGE_SAVE and
        STAGE_SAVE < STAGE_COMMIT and
        STAGE_COMMIT < STAGE_DONE;
    }

    // invariant: MAX_PIPELINE_STAGES >= 9
    invariant max_stages_sufficient {
        MAX_PIPELINE_STAGES >= 9;
    }

    // invariant: FAIL is distinct from all valid stages
    invariant fail_distinct {
        STAGE_FAIL != STAGE_INIT and
        STAGE_FAIL != STAGE_DONE;
    }

    // bench: full pipeline execution
    bench full_pipeline_bench {
        var stages : [10]u8;
        var results : [10]bool;
        var count : usize = 0;
        pipeline_run(stages[0..], results[0..], &count);
    }
}

