// Pattern Predictor - simple pattern prediction and anomaly detection
// Enables networks to learn patterns and predict future behavior

module pattern_predictor {
    use base::types;

    const MAX_SAMPLES: u32 = 16;
    const PATTERN_WINDOW: u32 = 8;
    const ANOMALY_THRESHOLD: u32 = 50;

    // Sample data point [value][timestamp][sequence][valid]
    fn create_sample(value: u32, timestamp: u32, sequence: u32, valid: u32) -> u32 {
        return (((value & 0xFF) << 24) |
                ((timestamp & 0xFF) << 16) |
                ((sequence & 0xFF) << 8) |
                (valid & 0x1));
    }

    fn get_sample_value(sample: u32) -> u32 {
        return ((sample >> 24) & 0xFF);
    }

    fn get_sample_timestamp(sample: u32) -> u32 {
        return ((sample >> 16) & 0xFF);
    }

    fn get_sample_sequence(sample: u32) -> u32 {
        return ((sample >> 8) & 0xFF);
    }

    fn get_sample_valid(sample: u32) -> u32 {
        return (sample & 0x1);
    }

    // Pattern storage [samples_array][pattern_count][trend_direction][last_update]
    fn create_pattern_storage(samples: u32, pattern_count: u32, trend: u32, last_update: u32) -> u32 {
        return (((samples & 0xFFFF) << 16) |
                ((pattern_count & 0xFF) << 8) |
                (trend & 0x3) |
                (last_update & 0x1));
    }

    fn get_pattern_samples(storage: u32) -> u32 {
        return ((storage >> 16) & 0xFFFF);
    }

    fn get_pattern_count(storage: u32) -> u32 {
        return ((storage >> 8) & 0xFF);
    }

    fn get_trend_direction(storage: u32) -> u32 {
        return (storage & 0x3);
    }

    // 16-sample storage. Sixteen samples cannot live in a u64: the old
    // packer silently DROPPED s8..s15 and the upper-half getter shifted a
    // u64 by 64 (with an unbalanced paren the parser swallowed whole).
    // A real array holds all sixteen.
    fn create_sample_array(s0: u32, s1: u32, s2: u32, s3: u32, s4: u32, s5: u32, s6: u32, s7: u32,
                            s8: u32, s9: u32, s10: u32, s11: u32, s12: u32, s13: u32, s14: u32, s15: u32) -> [u32; 16] {
        return [s0, s1, s2, s3, s4, s5, s6, s7, s8, s9, s10, s11, s12, s13, s14, s15];
    }

    fn get_sample_at(array: [u32; 16], index: u32) -> u32 {
        if (index < 16) {
            return array[index];
        }
        return 0;
    }

    // Calculate simple moving average
    fn calculate_moving_average(array: [u32; 16], window: u32) -> u32 {
        let sum = 0;
        let count = window;

        if (count > 16) { count = 16; }

        sum = sum + get_sample_value(get_sample_at(array, 0));
        sum = sum + get_sample_value(get_sample_at(array, 1));
        sum = sum + get_sample_value(get_sample_at(array, 2));
        sum = sum + get_sample_value(get_sample_at(array, 3));

        if (count > 4) {
            sum = sum + get_sample_value(get_sample_at(array, 4));
            sum = sum + get_sample_value(get_sample_at(array, 5));
            sum = sum + get_sample_value(get_sample_at(array, 6));
            sum = sum + get_sample_value(get_sample_at(array, 7));
        }

        if (count > 8) {
            sum = sum + get_sample_value(get_sample_at(array, 8));
            sum = sum + get_sample_value(get_sample_at(array, 9));
            sum = sum + get_sample_value(get_sample_at(array, 10));
            sum = sum + get_sample_value(get_sample_at(array, 11));
        }

        if (count > 12) {
            sum = sum + get_sample_value(get_sample_at(array, 12));
            sum = sum + get_sample_value(get_sample_at(array, 13));
            sum = sum + get_sample_value(get_sample_at(array, 14));
            sum = sum + get_sample_value(get_sample_at(array, 15));
        }

        return (sum / count);
    }

    // Detect trend direction (0=stable, 1=increasing, 2=decreasing)
    fn detect_trend(array: [u32; 16], samples: u32) -> u32 {
        if (samples < 2) { return 0; }

        let first = get_sample_value(get_sample_at(array, 0));
        let last = get_sample_value(get_sample_at(array, samples - 1));

        if (last > first + 5) {
            return 1; // Increasing
        } else if (last < first - 5) {
            return 2; // Decreasing
        } else {
            return 0; // Stable
        }
    }

    // Predict next value based on trend
    fn predict_next_value(array: [u32; 16], samples: u32) -> u32 {
        let trend = detect_trend(array, samples);
        let current = get_sample_value(get_sample_at(array, samples - 1));

        if (trend == 1) {
            // Increasing trend
            return current + 10;
        } else if (trend == 2) {
            // Decreasing trend
            let predicted = current - 10;
            if (predicted < 0) { predicted = 0; }
            return predicted;
        } else {
            // Stable trend
            return current;
        }
    }

    // Check if current value is anomalous
    fn is_anomalous(array: [u32; 16], samples: u32, current_value: u32) -> u32 {
        let predicted = predict_next_value(array, samples);

        if (predicted > current_value) {
            return (predicted - current_value);
        } else {
            return (current_value - predicted);
        }
    }

    // Simple pattern matching (repeating sequence)
    fn detect_repeating_pattern(array: [u32; 16], samples: u32) -> u32 {
        if (samples < 4) { return 0; }

        let v0 = get_sample_value(get_sample_at(array, 0));
        let v1 = get_sample_value(get_sample_at(array, 1));
        let v2 = get_sample_value(get_sample_at(array, 2));
        let v3 = get_sample_value(get_sample_at(array, 3));

        // Check for simple 2-value pattern: A,B,A,B,A,B
        if (v0 == v2 && v1 == v3 && v0 != v1) {
            return 1; // Pattern found
        }

        // Check for simple 3-value pattern: A,B,C,A,B,C
        if (samples >= 6) {
            let v4 = get_sample_value(get_sample_at(array, 4));
            let v5 = get_sample_value(get_sample_at(array, 5));

            if (v0 == v3 && v1 == v4 && v2 == v5) {
                return 1; // Pattern found
            }
        }

        return 0; // No pattern
    }

    // Calculate variance (simple measure of variability)
    fn calculate_variance(array: [u32; 16], samples: u32) -> u32 {
        if (samples < 2) { return 0; }

        let avg = calculate_moving_average(array, samples);
        let sum_sq_diff = 0;

        if (samples >= 1) {
            // |sample - avg|: unsigned subtraction underflows when the sample is below
            // the mean, and the square only needs the magnitude.
            let v0: u32 = get_sample_value(get_sample_at(array, 0));
            let diff: u32 = 0;
            if (v0 >= avg) { diff = v0 - avg; } else { diff = avg - v0; }
            sum_sq_diff = sum_sq_diff + (diff * diff);
        }

        if (samples >= 2) {
            // |sample - avg|: unsigned subtraction underflows when the sample is below
            // the mean, and the square only needs the magnitude.
            let v1: u32 = get_sample_value(get_sample_at(array, 1));
            let diff: u32 = 0;
            if (v1 >= avg) { diff = v1 - avg; } else { diff = avg - v1; }
            sum_sq_diff = sum_sq_diff + (diff * diff);
        }

        if (samples >= 3) {
            // |sample - avg|: unsigned subtraction underflows when the sample is below
            // the mean, and the square only needs the magnitude.
            let v2: u32 = get_sample_value(get_sample_at(array, 2));
            let diff: u32 = 0;
            if (v2 >= avg) { diff = v2 - avg; } else { diff = avg - v2; }
            sum_sq_diff = sum_sq_diff + (diff * diff);
        }

        if (samples >= 4) {
            // |sample - avg|: unsigned subtraction underflows when the sample is below
            // the mean, and the square only needs the magnitude.
            let v3: u32 = get_sample_value(get_sample_at(array, 3));
            let diff: u32 = 0;
            if (v3 >= avg) { diff = v3 - avg; } else { diff = avg - v3; }
            sum_sq_diff = sum_sq_diff + (diff * diff);
        }

        if (samples < 2) { return 0; }
        return (sum_sq_diff / samples);
    }

