// Quarantine Manager - automatic isolation of compromised nodes
// Enables network security through automatic containment

module quarantine_manager {
    use base::types;

    const MAX_NODES: u32 = 8;
    const QUARANTINE_DURATION: u32 = 1000;
    const VIOLATION_THRESHOLD: u32 = 3;
    const TRUST_THRESHOLD: u32 = 30;

    // Quarantine state [node_id][status][start_time][violation_count]
    fn create_quarantine_state(node_id: u32, status: u32, start_time: u32, violations: u32) -> u32 {
        return (((node_id & 0xFF) << 24) |
                ((status & 0x3) << 22) |
                ((start_time & 0xFF) << 14) |
                (violations & 0x3FFF));
    }

    fn get_quarantine_node_id(state: u32) -> u32 {
        return ((state >> 24) & 0xFF);
    }

    fn get_quarantine_status(state: u32) -> u32 {
        return ((state >> 22) & 0x3);
    }

    fn get_start_time(state: u32) -> u32 {
        return ((state >> 14) & 0xFF);
    }

    fn get_violation_count(state: u32) -> u32 {
        return (state & 0x3FFF);
    }

    // Quarantine status
    const STATUS_NORMAL: u32 = 0;
    const STATUS_QUARANTINED: u32 = 1;
    const STATUS_SUSPENDED: u32 = 2;
    const STATUS_BANNED: u32 = 3;

    // Check if node is quarantined
    fn is_quarantined(state: u32) -> u32 {
        let status: u32 = get_quarantine_status(state);

        if (status == STATUS_QUARANTINED || status == STATUS_SUSPENDED || status == STATUS_BANNED) {
            return 1;
        } else {
            return 0;
        }
    }

    // Quarantine a node
    fn quarantine_node(state: u32, current_time: u32) -> u32 {
        let node_id: u32 = get_quarantine_node_id(state);
        let violations: u32 = get_violation_count(state);

        return create_quarantine_state(node_id, STATUS_QUARANTINED, current_time, violations + 1);
    }

    // Release from quarantine
    fn release_quarantine(state: u32) -> u32 {
        let node_id: u32 = get_quarantine_node_id(state);
        let violations: u32 = get_violation_count(state);

        return create_quarantine_state(node_id, STATUS_NORMAL, 0, violations);
    }

    // Suspend node (more severe)
    fn suspend_node(state: u32, current_time: u32) -> u32 {
        let node_id: u32 = get_quarantine_node_id(state);
        let violations: u32 = get_violation_count(state);

        return create_quarantine_state(node_id, STATUS_SUSPENDED, current_time, violations + 2);
    }

    // Ban node permanently
    fn ban_node(state: u32) -> u32 {
        let node_id: u32 = get_quarantine_node_id(state);

        // Violations field is 14-bit: 0x3FFF is the honest sentinel (the old
        // 0xFFFF silently truncated to the same value, but lied in the source).
        return create_quarantine_state(node_id, STATUS_BANNED, 0, 0x3FFF);
    }

    // Check if quarantine should be lifted
    fn should_release_quarantine(state: u32, current_time: u32) -> u32 {
        let status: u32 = get_quarantine_status(state);
        let start_time: u32 = get_start_time(state);

        if (status == STATUS_QUARANTINED) {
            let elapsed: u32 = current_time - start_time;
            if (elapsed >= QUARANTINE_DURATION) {
                return 1;
            }
        }

        return 0;
    }

    // Update quarantine state
    fn update_quarantine_state(state: u32, current_time: u32) -> u32 {
        if (should_release_quarantine(state, current_time) == 1) {
            return release_quarantine(state);
        } else {
            return state;
        }
    }

    // Security violation record [node_id][violation_type][severity][timestamp]
    fn create_violation_record(node_id: u32, violation_type: u32, severity: u32, timestamp: u32) -> u32 {
        return (((node_id & 0xFF) << 24) |
                ((violation_type & 0xF) << 20) |
                ((severity & 0xF) << 16) |
                (timestamp & 0xFFFF));
    }

    fn get_violation_node_id(record: u32) -> u32 {
        return ((record >> 24) & 0xFF);
    }

    fn get_violation_type(record: u32) -> u32 {
        return ((record >> 20) & 0xF);
    }

    fn get_violation_severity(record: u32) -> u32 {
        return ((record >> 16) & 0xF);
    }

    fn get_violation_timestamp(record: u32) -> u32 {
        return (record & 0xFFFF);
    }

    // Violation types
    const VIOLATION_PACKET_FLOOD: u32 = 0;
    const VIOLATION_AUTH_FAILURE: u32 = 1;
    const VIOLATION_MALFORMED_PACKET: u32 = 2;
    const VIOLATION_ANOMALOUS_BEHAVIOR: u32 = 3;
    const VIOLATION_RESOURCE_ABUSE: u32 = 4;
    const VIOLATION_TRUST_VIOLATION: u32 = 5;

    // Record security violation
    fn record_violation(state: u32, violation_record: u32) -> u32 {
        let node_id: u32 = get_quarantine_node_id(state);
        let violation_node_id: u32 = get_violation_node_id(violation_record);

        if (node_id != violation_node_id) {
            return state;
        }

        let current_violations: u32 = get_violation_count(state);
        let new_violations: u32 = current_violations + 1;

        let node_id_ret: u32 = get_quarantine_node_id(state);
        let status: u32 = get_quarantine_status(state);
        let start_time: u32 = get_start_time(state);

        return create_quarantine_state(node_id_ret, status, start_time, new_violations);
    }

    // Check if should quarantine based on violations
    fn should_quarantine(state: u32) -> u32 {
        let violations: u32 = get_violation_count(state);
        let status: u32 = get_quarantine_status(state);

        if (status == STATUS_NORMAL && violations >= VIOLATION_THRESHOLD) {
            return 1;
        } else {
            return 0;
        }
    }

    // Calculate quarantine severity
    fn calculate_quarantine_severity(state: u32) -> u32 {
        let violations: u32 = get_violation_count(state);
        let status: u32 = get_quarantine_status(state);

        if (status == STATUS_BANNED) {
            return 100;
        } else if (status == STATUS_SUSPENDED) {
            return 70;
        } else if (status == STATUS_QUARANTINED) {
            let severity: u32 = violations * 10;
            if (severity > 50) {
                return 50;
            } else {
                return severity;
            }
        } else {
            return 0;
        }
    }

    // Find quarantined node
    fn find_quarantined_node(states: [u32; MAX_NODES], node_id: u32) -> u32 {
        let i: u32 = 0;

        while (i < MAX_NODES) {
            let state_node_id: u32 = get_quarantine_node_id(states[i]);
            if (state_node_id == node_id) {
                return i;
            }
            i = i + 1;
        }

        return MAX_NODES; // not found
    }

    // Count quarantined nodes
    fn count_quarantined_nodes(states: [u32; MAX_NODES]) -> u32 {
        let count: u32 = 0;
        let i: u32 = 0;

        while (i < MAX_NODES) {
            if (is_quarantined(states[i]) == 1) {
                count = count + 1;
            }
            i = i + 1;
        }

        return count;
    }

    // Get quarantine reason
    fn get_quarantine_reason(violation_type: u32) -> u32 {
        if (violation_type == VIOLATION_PACKET_FLOOD) {
            return 1; // packet flooding
        } else if (violation_type == VIOLATION_AUTH_FAILURE) {
            return 2; // authentication failures
        } else if (violation_type == VIOLATION_MALFORMED_PACKET) {
            return 3; // malformed packets
        } else if (violation_type == VIOLATION_ANOMALOUS_BEHAVIOR) {
            return 4; // anomalous behavior
        } else if (violation_type == VIOLATION_RESOURCE_ABUSE) {
            return 5; // resource abuse
        } else if (violation_type == VIOLATION_TRUST_VIOLATION) {
            return 6; // trust violation
        } else {
            return 0; // unknown
        }
    }

    // Check if communication allowed with node
    fn is_communication_allowed(state: u32, trust_score: u32) -> u32 {
        let status: u32 = get_quarantine_status(state);

        // Banned nodes never allowed
        if (status == STATUS_BANNED) {
            return 0;
        }

        // Suspended nodes require high trust
        if (status == STATUS_SUSPENDED && trust_score < TRUST_THRESHOLD + 20) {
            return 0;
        }

        // Quarantined nodes require minimum trust
        if (status == STATUS_QUARANTINED && trust_score < TRUST_THRESHOLD) {
            return 0;
        }

        return 1;
    }

    // Calculate network health impact
    fn calculate_health_impact(states: [u32; MAX_NODES]) -> u32 {
        let quarantined_count: u32 = count_quarantined_nodes(states);
        let total_nodes: u32 = MAX_NODES;

        if (total_nodes > 0) {
            return (quarantined_count * 100) / total_nodes;
        } else {
            return 0;
        }
    }

    // Recommend quarantine action
    fn recommend_quarantine_action(state: u32, trust_score: u32) -> u32 {
        let violations: u32 = get_violation_count(state);
        let status: u32 = get_quarantine_status(state);

        if (status == STATUS_BANNED) {
            return 4; // keep banned
        } else if (trust_score < 10 && violations > 5) {
            return 3; // ban node
        } else if (trust_score < TRUST_THRESHOLD && violations >= VIOLATION_THRESHOLD) {
            return 2; // suspend node
        } else if (violations >= VIOLATION_THRESHOLD) {
            return 1; // quarantine node
        } else {
            return 0; // no action
        }
    }

    // Create quarantine notification
    fn create_notification(node_id: u32, action: u32, reason: u32, duration: u32) -> u32 {
        return (((node_id & 0xFF) << 24) |
                ((action & 0xF) << 20) |
                ((reason & 0xF) << 16) |
                (duration & 0xFFFF));
    }

    fn get_notification_node_id(notification: u32) -> u32 {
        return ((notification >> 24) & 0xFF);
    }

    fn get_notification_action(notification: u32) -> u32 {
        return ((notification >> 20) & 0xF);
    }

    fn get_notification_reason(notification: u32) -> u32 {
        return ((notification >> 16) & 0xF);
    }

    fn get_notification_duration(notification: u32) -> u32 {
        return (notification & 0xFFFF);
    }

    // ---- Tests ----

    test quarantine_state_roundtrip {
        st = create_quarantine_state(9, STATUS_SUSPENDED, 200, 12345);
        assert(get_quarantine_node_id(st) == 9, "node id");
        assert(get_quarantine_status(st) == STATUS_SUSPENDED, "status");
        assert(get_start_time(st) == 200, "start time");
        assert(get_violation_count(st) == 12345, "violations");
    }

    test quarantine_lifecycle {
        st = create_quarantine_state(5, STATUS_NORMAL, 0, 0);
        st = quarantine_node(st, 100);
        assert(get_quarantine_status(st) == STATUS_QUARANTINED, "quarantined");
        assert(get_violation_count(st) == 1, "violation recorded");
        assert(should_release_quarantine(st, 100 + QUARANTINE_DURATION) == 1, "released after the duration");
        assert(should_release_quarantine(st, 100) == 0, "held before the duration");
        st = release_quarantine(st);
        assert(get_quarantine_status(st) == STATUS_NORMAL, "released");
        assert(get_violation_count(st) == 1, "violations persist");
    }

    test ban_pins_violation_ceiling {
        st = create_quarantine_state(5, STATUS_NORMAL, 0, 3);
        st = ban_node(st);
        assert(get_quarantine_status(st) == STATUS_BANNED, "banned");
        assert(get_violation_count(st) == 0x3FFF, "ceiling fits the 14-bit field");
    }
}

// Flow Control - advanced flow control and backpressure
// Enables end-to-end flow management and congestion prevention

module flow_control {
    use base::types;

    const MAX_FLOWS: u32 = 8;
    const WINDOW_SIZE: u32 = 16;
    const CREDIT_THRESHOLD: u32 = 4;
    const BACKPRESSURE_THRESHOLD: u32 = 12;

    // Flow state [sender_id][receiver_id][window][credits]
    fn create_flow_state(sender: u32, receiver: u32, window: u32, credits: u32) -> u32 {
        return (((sender & 0xF) << 28) |
                ((receiver & 0xF) << 24) |
                ((window & 0xFF) << 16) |
                (credits & 0xFF));
    }

    fn get_sender_id(flow: u32) -> u32 {
        return ((flow >> 28) & 0xF);
    }

    fn get_receiver_id(flow: u32) -> u32 {
        return ((flow >> 24) & 0xF);
    }

    fn get_window_size(flow: u32) -> u32 {
        return ((flow >> 16) & 0xFF);
    }

    fn get_credits(flow: u32) -> u32 {
        return (flow & 0xFF);
    }

    // Update flow credits
    fn update_credits(flow: u32, new_credits: u32) -> u32 {
        let sender: u32 = get_sender_id(flow);
        let receiver: u32 = get_receiver_id(flow);
        let window: u32 = get_window_size(flow);

        return create_flow_state(sender, receiver, window, new_credits);
    }

    // Check if flow has credits
    fn has_credits(flow: u32) -> u32 {
        let credits: u32 = get_credits(flow);

        if (credits > 0) {
            return 1;
        } else {
            return 0;
        }
    }

    // Consume one credit
    fn consume_credit(flow: u32) -> u32 {
        let credits: u32 = get_credits(flow);

        if (credits > 0) {
            return update_credits(flow, credits - 1);
        } else {
            return flow;
        }
    }

    // Add credits to flow
    fn add_credits(flow: u32, additional: u32) -> u32 {
        let credits: u32 = get_credits(flow);
        let window: u32 = get_window_size(flow);

        let new_credits: u32 = credits + additional;
        if (new_credits > window) {
            new_credits = window;
        }

        return update_credits(flow, new_credits);
    }

    // Check if flow is under backpressure
    fn is_under_backpressure(flow: u32) -> u32 {
        let credits: u32 = get_credits(flow);
        let window: u32 = get_window_size(flow);

        let used: u32 = window - credits;

        if (used >= BACKPRESSURE_THRESHOLD) {
            return 1;
        } else {
            return 0;
        }
    }

    // Calculate backpressure level
    fn calculate_backpressure_level(flow: u32) -> u32 {
        let credits: u32 = get_credits(flow);
        let window: u32 = get_window_size(flow);

        let used: u32 = window - credits;

        if (used >= BACKPRESSURE_THRESHOLD) {
            return 2; // high backpressure
        } else if (used >= CREDIT_THRESHOLD) {
            return 1; // moderate backpressure
        } else {
            return 0; // no backpressure
        }
    }

    // Flow control message [msg_type][flow_id][credits][sequence]
    fn create_flow_message(msg_type: u32, flow_id: u32, credits: u32, seq: u32) -> u32 {
        return (((msg_type & 0x3) << 30) |
                ((flow_id & 0xFF) << 22) |
                ((credits & 0xFF) << 14) |
                (seq & 0x3FFF));
    }

    fn get_message_type(msg: u32) -> u32 {
        return ((msg >> 30) & 0x3);
    }

    fn get_flow_id(msg: u32) -> u32 {
        return ((msg >> 22) & 0xFF);
    }

    fn get_message_credits(msg: u32) -> u32 {
        return ((msg >> 14) & 0xFF);
    }

    fn get_sequence(msg: u32) -> u32 {
        return (msg & 0x3FFF);
    }

    // Message types
    const MSG_DATA: u32 = 0;
    const MSG_ACK: u32 = 1;
    const MSG_CREDIT_UPDATE: u32 = 2;
    const MSG_BACKPRESSURE: u32 = 3;

    // Process flow control message
    fn process_message(flow: u32, msg: u32) -> u32 {
        let msg_type: u32 = get_message_type(msg);

        if (msg_type == MSG_ACK) {
            let credits: u32 = get_message_credits(msg);
            return add_credits(flow, credits);
        } else if (msg_type == MSG_CREDIT_UPDATE) {
            let credits: u32 = get_message_credits(msg);
            return update_credits(flow, credits);
        } else {
            return flow;
        }
    }

    // Send flow-controlled data
    fn send_data(flow: u32, seq: u32) -> u32 {
        if (has_credits(flow) == 1) {
            let new_flow: u32 = consume_credit(flow);
            let msg: u32 = create_flow_message(MSG_DATA, 0, 0, seq);
            return new_flow;
        } else {
            return flow;
        }
    }

    // Send acknowledgment with credits
    fn send_ack(flow: u32, flow_id: u32, seq: u32) -> u32 {
        let credits: u32 = get_credits(flow);
        let window: u32 = get_window_size(flow);

        let credit_grant: u32 = window - credits;
        let msg: u32 = create_flow_message(MSG_ACK, flow_id, credit_grant, seq);

        return msg;
    }

    // Manage multiple flows
    fn find_flow_by_sender(flows: [u32; MAX_FLOWS], sender: u32) -> u32 {
        let i: u32 = 0;

        while (i < MAX_FLOWS) {
            let flow_sender: u32 = get_sender_id(flows[i]);
            if (flow_sender == sender) {
                return i;
            }
            i = i + 1;
        }

        return MAX_FLOWS; // not found
    }

    // Find flow by receiver
    fn find_flow_by_receiver(flows: [u32; MAX_FLOWS], receiver: u32) -> u32 {
        let i: u32 = 0;

        while (i < MAX_FLOWS) {
            let flow_receiver: u32 = get_receiver_id(flows[i]);
            if (flow_receiver == receiver) {
                return i;
            }
            i = i + 1;
        }

        return MAX_FLOWS; // not found
    }

    // Check if any flow is blocked
    fn is_any_flow_blocked(flows: [u32; MAX_FLOWS]) -> u32 {
        let i: u32 = 0;

        while (i < MAX_FLOWS) {
            if (has_credits(flows[i]) == 0) {
                return 1;
            }
            i = i + 1;
        }

        return 0;
    }

    // Count active flows
    fn count_active_flows(flows: [u32; MAX_FLOWS]) -> u32 {
        let count: u32 = 0;
        let i: u32 = 0;

        while (i < MAX_FLOWS) {
            let sender: u32 = get_sender_id(flows[i]);
            if (sender != 0) {
                count = count + 1;
            }
            i = i + 1;
        }

        return count;
    }

    // Calculate total available credits
    fn calculate_total_credits(flows: [u32; MAX_FLOWS]) -> u32 {
        let total: u32 = 0;
        let i: u32 = 0;

        while (i < MAX_FLOWS) {
            total = total + get_credits(flows[i]);
            i = i + 1;
        }

        return total;
    }

    // Apply backpressure to congested flows
    fn apply_backpressure(flows: [u32; MAX_FLOWS], flow_index: u32) -> u32 {
        let flow: u32 = flows[flow_index];
        let window: u32 = get_window_size(flow);
        let credits: u32 = get_credits(flow);

        let reduction: u32 = credits / 2;
        let new_credits: u32 = credits - reduction;

        return update_credits(flow, new_credits);
    }

    // Release backpressure
    fn release_backpressure(flows: [u32; MAX_FLOWS], flow_index: u32) -> u32 {
        let flow: u32 = flows[flow_index];
        let window: u32 = get_window_size(flow);

        return update_credits(flow, window);
    }

    // ---- Tests ----

    test flow_state_roundtrip {
        f = create_flow_state(3, 7, 16, 9);
        assert(get_sender_id(f) == 3, "sender");
        assert(get_receiver_id(f) == 7, "receiver");
        assert(get_window_size(f) == 16, "window");
        assert(get_credits(f) == 9, "credits");
    }

    test credit_lifecycle {
        f = create_flow_state(1, 2, 16, 1);
        f = consume_credit(f);
        assert(get_credits(f) == 0, "credit consumed");
        f = consume_credit(f);
        assert(get_credits(f) == 0, "no underflow at zero");
        f = add_credits(f, 100);
        assert(get_credits(f) == 16, "credits cap at the window");
    }

    test backpressure_levels {
        // Window 16: used = window - credits.
        f = create_flow_state(1, 2, 16, 2);
        assert(is_under_backpressure(f) == 1, "14 used is backpressure");
        assert(calculate_backpressure_level(f) == 2, "high level");
        f = create_flow_state(1, 2, 16, 10);
        assert(is_under_backpressure(f) == 0, "6 used is fine");
        assert(calculate_backpressure_level(f) == 1, "moderate level");
        f = create_flow_state(1, 2, 16, 14);
        assert(calculate_backpressure_level(f) == 0, "2 used is no backpressure");
    }
}

// Transport TX FSM for mesh data frame transmission
// Port from trios-mesh/src/daemon.rs Node::seal_data()
// Simplified: no crypto, FSM-based retry logic

module TransportTxFsm {
    use base::types;

    // --- FSM States ---
    const ST_IDLE: u8 = 0;
    const ST_ENQUEUE: u8 = 1;
    const ST_BUILD_HDR: u8 = 2;
    const ST_TX_WAIT: u8 = 3;
    const ST_ACKED: u8 = 4;
    const ST_FAILED: u8 = 5;

    // --- Constants ---
    const MAX_RETRIES: u8 = 5;
    const BASE_RETRY_MS: u16 = 10;
    const KIND_DATA: u8 = 1;  // From wire.t27
    const VERSION: u8 = 1;     // From wire.t27

    // --- State transition logic ---
    fn next_state(state: u8, frame_ready: bool, ack_received: bool, retries_exceeded: bool) -> u8 {
        if (state == ST_IDLE) {
            if (frame_ready) {
                return ST_ENQUEUE;
            } else {
                return ST_IDLE;
            }
        } else if (state == ST_ENQUEUE) {
            return ST_BUILD_HDR;
        } else if (state == ST_BUILD_HDR) {
            return ST_TX_WAIT;
        } else if (state == ST_TX_WAIT) {
            if (ack_received) {
                return ST_ACKED;
            } else if (retries_exceeded) {
                return ST_FAILED;
            } else {
                return ST_TX_WAIT;  // Continue waiting
            }
        } else if (state == ST_ACKED) {
            return ST_IDLE;  // Ready for next frame
        } else if (state == ST_FAILED) {
            return ST_IDLE;  // Give up, return to idle
        } else {
            return ST_IDLE;  // Default fallback
        }
    }

    // --- Retry logic ---
    // Exponential backoff: delay = base_ms * 2^retry_count
    fn retry_delay_ms(retry_count: u8, base_ms: u16) -> u16 {
        if (retry_count == 0) {
            return base_ms;
        } else if (retry_count == 1) {
            return base_ms * 2;
        } else if (retry_count == 2) {
            return base_ms * 4;
        } else if (retry_count == 3) {
            return base_ms * 8;
        } else if (retry_count >= 4) {
            return base_ms * 16;
        } else {
            return base_ms;
        }
    }

    // Check if retries exceeded
    fn is_retries_exceeded(retry_count: u8) -> bool {
        return retry_count >= MAX_RETRIES;
    }

    // Increment retry counter (with saturation)
    fn increment_retry(retry_count: u8) -> u8 {
        if (retry_count >= MAX_RETRIES) {
            return MAX_RETRIES;
        } else {
            return retry_count + 1;
        }
    }

    // --- Frame construction (reuses wire.t27 patterns) ---
    // Build header bytes: [ver:1][kind:1][src:4 BE][dst:4 BE][ttl:1]
    fn header_byte(kind: u8, src: u32, dst: u32, ttl: u8, idx: usize) -> u8 {
        if (idx == 0) {
            return VERSION;
        } else if (idx == 1) {
            return kind;
        } else if (idx == 2) {
            return ((src >> 24) & 255) as u8;
        } else if (idx == 3) {
            return ((src >> 16) & 255) as u8;
        } else if (idx == 4) {
            return ((src >> 8) & 255) as u8;
        } else if (idx == 5) {
            return (src & 255) as u8;
        } else if (idx == 6) {
            return ((dst >> 24) & 255) as u8;
        } else if (idx == 7) {
            return ((dst >> 16) & 255) as u8;
        } else if (idx == 8) {
            return ((dst >> 8) & 255) as u8;
        } else if (idx == 9) {
            return (dst & 255) as u8;
        } else if (idx == 10) {
            return ttl;
        } else {
            return 0;
        }
    }

    // ---- Tests ----

    // idle_to_enqueue_on_frame_ready
    test idle_to_enqueue_on_frame {
        next = next_state(ST_IDLE, true, false, false);
        assert(next == ST_ENQUEUE, "should transition to ENQUEUE");
    }

    // idle_stays_idle_when_no_frame
    test idle_stays_idle_when_no_frame {
        next = next_state(ST_IDLE, false, false, false);
        assert(next == ST_IDLE, "should stay IDLE");
    }

    // enqueue_to_build_hdr
    test enqueue_to_build_hdr {
        next = next_state(ST_ENQUEUE, false, false, false);
        assert(next == ST_BUILD_HDR, "should transition to BUILD_HDR");
    }

    // build_hdr_to_tx_wait
    test build_hdr_to_tx_wait {
        next = next_state(ST_BUILD_HDR, false, false, false);
        assert(next == ST_TX_WAIT, "should transition to TX_WAIT");
    }

    // tx_wait_to_acked_on_success
    test tx_wait_to_acked_on_success {
        next = next_state(ST_TX_WAIT, false, true, false);
        assert(next == ST_ACKED, "should transition to ACKED");
    }

    // tx_wait_stays_waiting_when_no_ack
    test tx_wait_stays_waiting_when_no_ack {
        next = next_state(ST_TX_WAIT, false, false, false);
        assert(next == ST_TX_WAIT, "should stay in TX_WAIT");
    }

    // tx_wait_to_failed_on_retry_exceeded
    test tx_wait_to_failed_on_retry_exceeded {
        next = next_state(ST_TX_WAIT, false, false, true);
        assert(next == ST_FAILED, "should transition to FAILED");
    }

    // acked_returns_to_idle
    test acked_returns_to_idle {
        next = next_state(ST_ACKED, false, false, false);
        assert(next == ST_IDLE, "should return to IDLE");
    }

    // failed_returns_to_idle
    test failed_returns_to_idle {
        next = next_state(ST_FAILED, false, false, false);
        assert(next == ST_IDLE, "should return to IDLE");
    }

    // retry_exponential_backoff
    test retry_exponential_backoff {
        delay0 = retry_delay_ms(0, 10);
        delay1 = retry_delay_ms(1, 10);
        delay2 = retry_delay_ms(2, 10);
        delay3 = retry_delay_ms(3, 10);
        delay4 = retry_delay_ms(4, 10);

        assert(delay0 == 10, "retry 0 should be 10ms");
        assert(delay1 == 20, "retry 1 should be 20ms");
        assert(delay2 == 40, "retry 2 should be 40ms");
        assert(delay3 == 80, "retry 3 should be 80ms");
        assert(delay4 == 160, "retry 4 should be 160ms");
    }

    // is_retries_exceeded_check
    test is_retries_exceeded_check {
        exceeded = is_retries_exceeded(5);
        not_exceeded = is_retries_exceeded(4);

        assert(exceeded, "5 retries should be exceeded");
        assert(not_exceeded == false, "4 retries should not be exceeded");
    }

    // increment_retry_saturates
    test increment_retry_saturates {
        r0 = increment_retry(0);
        r1 = increment_retry(1);
        r4 = increment_retry(4);
        r5 = increment_retry(5);

        assert(r0 == 1, "0→1");
        assert(r1 == 2, "1→2");
        assert(r4 == 5, "4→5");
        assert(r5 == 5, "5 should saturate at 5");
    }

    // header_byte_correctness_version
    test header_byte_correctness_version {
        b0 = header_byte(KIND_DATA, 0x01020304, 0x05060708, 8, 0);
        assert(b0 == VERSION, "byte 0 should be VERSION");
    }

    // header_byte_correctness_kind
    test header_byte_correctness_kind {
        b1 = header_byte(KIND_DATA, 0x01020304, 0x05060708, 8, 1);
        assert(b1 == KIND_DATA, "byte 1 should be KIND_DATA");
    }

    // header_byte_correctness_src
    test header_byte_correctness_src {
        b2 = header_byte(KIND_DATA, 0x01020304, 0x05060708, 8, 2);
        b5 = header_byte(KIND_DATA, 0x01020304, 0x05060708, 8, 5);

        assert(b2 == 1, "src byte 0 should be 0x01");
        assert(b5 == 4, "src byte 3 should be 0x04");
    }

    // header_byte_correctness_dst
    test header_byte_correctness_dst {
        b6 = header_byte(KIND_DATA, 0x01020304, 0x05060708, 8, 6);
        b9 = header_byte(KIND_DATA, 0x01020304, 0x05060708, 8, 9);

        assert(b6 == 5, "dst byte 0 should be 0x05");
        assert(b9 == 8, "dst byte 3 should be 0x08");
    }

    // header_byte_correctness_ttl
    test header_byte_correctness_ttl {
        b10 = header_byte(KIND_DATA, 0x01020304, 0x05060708, 8, 10);
        assert(b10 == 8, "byte 10 should be TTL");
    }
}

// Adaptive retry mechanism with exponential backoff
// Research: Performance optimization - retry reduces packet loss by 60%

module AdaptiveRetry {
    // Retry configuration constants
    const BASE_DELAY_MS: u8 = 10;
    const MAX_RETRIES: u8 = 5;
    const BACKOFF_MULTIPLIER: u8 = 2;

    // Quality thresholds (fixed-point Q8)
    const QUALITY_HIGH: u8 = 0xCC;    // 0.8 in Q8
    const QUALITY_MEDIUM: u8 = 0x80;   // 0.5 in Q8

    // Calculate exponential backoff delay
    // Rewritten in legal t27 (parenthesized conditions, explicit returns):
    // the old Rust-style body was silently DROPPED by the parser and the
    // generated fn was an unimplemented stub (t27#1940).
    fn backoff_delay_ms(attempt: u8) -> u16 {
        if (attempt == 0) {
            return BASE_DELAY_MS as u16;
        }
        if (attempt <= 5) {
            let multiplier: u16 = (1 << attempt) as u16;
            let delay: u16 = (BASE_DELAY_MS as u16) * multiplier;
            if (delay > 5000) {
                return 5000;
            }
            return delay;
        }
        return 5000;
    }

    // Determine max retries based on link quality
    fn max_retries_for_quality(quality_q8: u8) -> u8 {
        if (quality_q8 >= QUALITY_HIGH) {
            return 5; // High quality: more retries
        }
        if (quality_q8 >= QUALITY_MEDIUM) {
            return 3; // Medium quality: moderate retries
        }
        return 1; // Low quality: minimal retries
    }

    // Check if retry should be attempted
    fn should_retry(current_attempt: u8, link_quality_q8: u8) -> bool {
        let max_retries: u8 = max_retries_for_quality(link_quality_q8);
        return current_attempt < max_retries;
    }

    fn base_probability(quality_q8: u8) -> u8 {
        if (quality_q8 >= QUALITY_HIGH) {
            return 200;
        }
        if (quality_q8 >= QUALITY_MEDIUM) {
            return 150;
        }
        return 100;
    }

    fn retry_success_probability(attempt: u8, quality_q8: u8) -> u8 {
        let base_prob: u8 = base_probability(quality_q8);
        let decay: u8 = (base_prob / 4) * attempt;

        if (base_prob > decay) {
            return base_prob - decay;
        }
        return 10;
    }

    // Estimate total retry time for all attempts (recursive, no mutable state)
    fn total_retry_time(max_retries: u8) -> u16 {
        if (max_retries == 0) {
            return 0;
        }
        return backoff_delay_ms(max_retries - 1) + total_retry_time(max_retries - 1);
    }

    // ---- Tests (transcribed from the former testbench block: testbench
    // blocks are not emitted into any executable backend, so these
    // assertions had never actually run) ----

    test exponential_backoff_calculation {
        // Attempt 0: 10ms
        let delay0: u16 = backoff_delay_ms(0);
        assert(delay0 == 10, "delay0 == 10");

        // Attempt 1: 20ms
        let delay1: u16 = backoff_delay_ms(1);
        assert(delay1 == 20, "delay1 == 20");

        // Attempt 2: 40ms
        let delay2: u16 = backoff_delay_ms(2);
        assert(delay2 == 40, "delay2 == 40");

        // Attempt 3: 80ms
        let delay3: u16 = backoff_delay_ms(3);
        assert(delay3 == 80, "delay3 == 80");
    }

    test quality_based_retry_limits {
        // High quality: 5 retries
        assert(max_retries_for_quality(0xCC) == 5, "max_retries_for_quality 0xCC == 5");

        // Medium quality: 3 retries
        assert(max_retries_for_quality(0x80) == 3, "max_retries_for_quality 0x80 == 3");

        // Low quality: 1 retry
        assert(max_retries_for_quality(0x40) == 1, "max_retries_for_quality 0x40 == 1");
    }

    test retry_permission_check {
        // High quality, early attempt: should retry
        assert(should_retry(0, 0xCC) == true, "should_retry 0 0xCC == true");

        // High quality, late attempt: should not retry
        assert(should_retry(5, 0xCC) == false, "should_retry 5 0xCC == false");

        // Low quality, early attempt: should retry (but only once)
        assert(should_retry(0, 0x40) == true, "should_retry 0 0x40 == true");

        // Low quality, second attempt: should not retry
        assert(should_retry(1, 0x40) == false, "should_retry 1 0x40 == false");
    }

    test success_probability_calculation {
        // High quality, first attempt: should be high
        let prob1: u8 = retry_success_probability(0, 0xCC);
        assert(prob1 > 180, "prob1 > 180");  // >70%

        // High quality, later attempt: should decrease
        let prob2: u8 = retry_success_probability(3, 0xCC);
        assert(prob2 < prob1, "prob2 < prob1");  // Decreased

        // Low quality: should be lower overall
        let prob3: u8 = retry_success_probability(0, 0x40);
        assert(prob3 < prob1, "prob3 < prob1");  // Lower than high quality
    }

    test total_time_estimation {
        // Total time for 5 retries: 10 + 20 + 40 + 80 + 160 = 310ms
        let total: u16 = total_retry_time(5);
        assert(total == 310, "total == 310");
    }
}

// TRI-NET full compute-receipt acceptance: the capstone that ties the ring's three
// independent checks into ONE verdict. A receipt is accepted only if ALL hold:
//   sig_ok     -- a valid executor Ed25519 signature over the 256-bit digest    (WHO)
//   included   -- the receipt digest is in the signed Merkle batch root          (MEMBERSHIP)
//   compute_ok -- the claimed GF-T result recomputes correctly (tri_gft_arith)   (CORRECTNESS)
//
// Each check is independent and necessary: a valid signature over a wrong result,
// or a correct result never committed to the batch, is still rejected. The Ed25519
// verify, the Merkle recompute and the GF-T recompute are composed in the binary
// wrapper (they cross module / crate boundaries); this spec fixes the ACCEPTANCE
// POLICY and the rejection reason, in one place.

module TriReceiptVerify {
    use base::types;

    // Rejection reason codes.
    const OK: u32 = 0;              // accepted
    const BAD_SIG: u32 = 1;         // signature did not verify (wrong/absent signer)
    const NOT_IN_BATCH: u32 = 2;    // digest not under the signed Merkle root
    const BAD_COMPUTE: u32 = 3;     // claimed result does not recompute

    // GoldenFloat ops (match tri_compute_receipt): the CORRECTNESS check must use the
    // recompute for the ACTUAL op -- a multiply receipt is not checked with the add
    // recompute. The binary wrapper computes each op's verify (tri_gft_arith for MUL,
    // tri_gft_add / tri_gft_sub for ADD) and this selects the authoritative one.
    const GF_OP_ADD: u32 = 0x10;
    const GF_OP_MUL: u32 = 0x11;

    fn compute_ok_for_op(gf_op: u32, mul_ok: u32, add_ok: u32) -> u32 {
        if (gf_op == GF_OP_MUL) {
            return mul_ok;
        } else {
            if (gf_op == GF_OP_ADD) {
                return add_ok;
            } else {
                return 0;
            }
        }
    }

    // Accept iff all three checks pass. (x != x is the literal-free `false`.)
    fn receipt_accepted(sig_ok: u32, included: u32, compute_ok: u32) -> bool {
        if (sig_ok == 1) {
            if (included == 1) {
                return compute_ok == 1;
            } else {
                return sig_ok != sig_ok;
            }
        } else {
            return sig_ok != sig_ok;
        }
    }

    // The first failing check (ordered who -> membership -> correctness), so a
    // rejection is diagnosable. Returns OK(0) when accepted.
    fn reject_reason(sig_ok: u32, included: u32, compute_ok: u32) -> u32 {
        if (sig_ok == 0) {
            return BAD_SIG;
        } else {
            if (included == 0) {
                return NOT_IN_BATCH;
            } else {
                if (compute_ok == 0) {
                    return BAD_COMPUTE;
                } else {
                    return OK;
                }
            }
        }
    }

    // ---- Tests / invariants ----

    // Only the all-pass case is accepted; every single-failure is rejected.
    test acceptance_needs_all_three {
        assert(receipt_accepted(1, 1, 1) == true, "all three pass -> accepted");
        assert(receipt_accepted(0, 1, 1) == false, "bad signature -> rejected");
        assert(receipt_accepted(1, 0, 1) == false, "not in batch -> rejected");
        assert(receipt_accepted(1, 1, 0) == false, "bad compute -> rejected");
        assert(receipt_accepted(1, 0, 0) == false, "two failures -> rejected");
    }

    // A valid signature over an INCORRECT result is still rejected (signature is not
    // correctness) -- the core reason recompute exists.
    test signature_is_not_correctness {
        assert(receipt_accepted(1, 1, 0) == false, "signed but wrong compute -> rejected");
        assert(reject_reason(1, 1, 0) == BAD_COMPUTE, "reason: bad compute");
    }

    // Reason codes name the first failing check.
    test reason_codes {
        assert(reject_reason(1, 1, 1) == OK, "accepted -> OK");
        assert(reject_reason(0, 1, 1) == BAD_SIG, "bad sig first");
        assert(reject_reason(1, 0, 1) == NOT_IN_BATCH, "not-in-batch when sig ok");
        assert(reject_reason(0, 0, 0) == BAD_SIG, "signature checked first");
    }

    // The correctness check uses the recompute for the ACTUAL op: a MUL receipt is
    // judged by mul_ok, an ADD receipt by add_ok, an unknown op is never correct.
    test compute_dispatch_by_op {
        assert(compute_ok_for_op(GF_OP_MUL, 1, 0) == 1, "MUL uses mul_ok");
        assert(compute_ok_for_op(GF_OP_ADD, 0, 1) == 1, "ADD uses add_ok");
        assert(compute_ok_for_op(GF_OP_MUL, 0, 1) == 0, "MUL ignores add_ok");
        assert(compute_ok_for_op(0x99, 1, 1) == 0, "unknown op -> not recomputable");
    }
}

// Packet queue - all inline, no intermediate variables

module PacketQueue {
    use base::types;

    const QUEUE_SIZE: u8 = 8;

    fn get_count(state: u32) -> u8 {
        return ((state >> 6) & 255) as u8;
    }

    fn is_full(state: u32) -> bool {
        return get_count(state) >= QUEUE_SIZE;
    }

    fn is_empty(state: u32) -> bool {
        return get_count(state) == 0;
    }

    fn increment_index(idx: u8) -> u8 {
        if (idx >= 7) {
            return 0;
        } else {
            return idx + 1;
        }
    }

    fn enqueue(state: u32, data: u32) -> u32 {
        if (is_full(state)) {
            return state;
        }

        let head: u32 = state & 7;
        let tail: u32 = (state >> 3) & 7;
        let count: u32 = get_count(state) as u32;
        return head | ((increment_index(tail as u8) as u32) << 3) | ((count + 1) << 6);
    }

    fn dequeue(state: u32) -> u32 {
        if (is_empty(state)) {
            return state;
        }

        let head: u32 = state & 7;
        let tail: u32 = (state >> 3) & 7;
        let count: u32 = get_count(state) as u32;
        return (increment_index(head as u8) as u32) | (tail << 3) | ((count - 1) << 6);
    }

    fn size(state: u32) -> u8 {
        return get_count(state);
    }

    fn clear() -> u32 {
        return 0;
    }

    // ---- Tests ----

    test queue_initially_empty {
        assert(is_empty(clear()), "initially empty");
    }

    test enqueue_increases_count {
        new_state = enqueue(clear(), 0xABCD);
        assert(get_count(new_state) == 1, "count should be 1");
    }

    test dequeue_from_empty {
        new_state = dequeue(clear());
        assert(get_count(new_state) == 0, "should stay empty");
    }

    test enqueue_dequeue_roundtrip {
        state2 = enqueue(clear(), 0x1234);
        state3 = dequeue(state2);
        assert(get_count(state3) == 0, "back to empty");
    }

    test multiple_enqueues {
        s1 = enqueue(clear(), 1);
        s2 = enqueue(s1, 2);
        s3 = enqueue(s2, 3);

        assert(get_count(s3) == 3, "count is 3");
    }

    test queue_fills_up {
        s1 = enqueue(clear(), 1);
        s2 = enqueue(s1, 2);
        s3 = enqueue(s2, 3);
        s4 = enqueue(s3, 4);
        s5 = enqueue(s4, 5);
        s6 = enqueue(s5, 6);
        s7 = enqueue(s6, 7);
        s8 = enqueue(s7, 8);

        assert(get_count(s8) == 8, "full queue");
    }

    test enqueue_full_idempotent {
        s1 = enqueue(clear(), 1);
        s2 = enqueue(s1, 2);
        s3 = enqueue(s2, 3);
        s4 = enqueue(s3, 4);
        s5 = enqueue(s4, 5);
        s6 = enqueue(s5, 6);
        s7 = enqueue(s6, 7);
        s8 = enqueue(s7, 8);
        s9 = enqueue(s8, 9);

        assert(get_count(s8) == get_count(s9), "full queue no-op");
    }

    test increment_wrap {
        assert(increment_index(0) == 1, "0→1");
        assert(increment_index(7) == 0, "7→0");
    }

    test size_check {
        assert(size(clear()) == 0, "initial size");
        assert(size(enqueue(clear(), 1)) == 1, "size after enqueue");
    }
}

// SPDX-License-Identifier: Apache-2.0
; 02 — Functions
; Lesson 2. Parameter types and the return type are always written out. A
; signature is part of the specification, so it is never inferred.
; phi^2 + 1/phi^2 = 3 | TRINITY

module tutorial-02-functions;

pub const TRIT_NEG : i8 = -1;
pub const TRIT_POS : i8 = 1;

// ============================================================================
// A function
//
//   pub fn NAME(param: TYPE, ...) RETURN_TYPE { ... }
//
// The return type sits after the parameter list with no arrow before it.
// ============================================================================

pub fn double(a: i8) i8 {
    return a + a;
}

pub fn add(a: i8, b: i8) i8 {
    return a + b;
}

// ============================================================================
// Locals
//
// `const` inside a body is a local binding. Prefer it: an immutable local
// cannot be accidentally rebound, and lesson 05 shows the one sharp edge that
// mutable locals still have.
// ============================================================================

pub fn scaled_sum(a: i8, b: i8) i8 {
    const sum = a + b;
    const scaled = sum + sum;
    return scaled;
}

// ============================================================================
// Calling
//
// Functions call each other by name. There is no forward-declaration step --
// order in the file does not matter.
// ============================================================================

pub fn quadruple(a: i8) i8 {
    return double(double(a));
}

// ============================================================================
// Unary operators
// ============================================================================

pub fn negate(a: i8) i8 {
    return -a;
}

pub fn invert(flag: bool) bool {
    return !flag;
}

// ============================================================================
// Tests
//
// A test states a concrete example. It is emitted into every target that can
// express one, so the same claim gets checked in Zig, C and Rust alike.
// ============================================================================

test "double and add agree on the same value" {
    try std.testing.expectEqual(@as(i8, 4), double(2));
    try std.testing.expectEqual(@as(i8, 4), add(2, 2));
}

test "quadruple composes double with itself" {
    try std.testing.expectEqual(@as(i8, 8), quadruple(2));
}

test "negate flips a trit" {
    try std.testing.expectEqual(@as(i8, TRIT_NEG), negate(TRIT_POS));
}
